export const SOURCES: Record<string, string> = {
  "server.ts": "/**\n * Copilot Runtime for this harness.\n *\n * Shape comes from the Angular quickstart's Node runtime server, with the\n * agent swapped for the LlamaIndex backend in `../backend`.\n *\n * That backend exposes a plain AG-UI endpoint —\n * `app.include_router(get_ag_ui_workflow_router(...))` in backend/main.py\n * mounts a single `POST /run` that streams AG-UI events over SSE.\n *\n * `LlamaIndexAgent` from `@ag-ui/llamaindex` is the binding for that endpoint.\n * It is an `HttpAgent` subclass that pins the AG-UI protocol version the\n * LlamaIndex workflow router speaks, and substitutes a placeholder body for\n * empty tool results, which that router rejects.\n *\n * `default` and `support` resolve to the same LlamaIndex process.\n * `support` exists so the doc snippets that use `agentId=\"support\"` (Chat UI,\n * Threads) run verbatim.\n *\n * `a2ui: {}` enables A2UIMiddleware for every registered agent, per\n * https://docs.copilotkit.ai/angular/llamaindex/guides/a2ui\n * — it is a runtime-side middleware and is independent of which agent binding\n * is used.\n *\n * Ports: backend/main.py binds 8000, so the runtime sits on 8201. Override\n * either side with PORT / LLAMAINDEX_AGENT_URL.\n */\nimport { createServer } from \"node:http\";\nimport { CopilotRuntime } from \"@copilotkit/runtime/v2\";\nimport { createCopilotNodeListener } from \"@copilotkit/runtime/v2/node\";\nimport { LlamaIndexAgent } from \"@ag-ui/llamaindex\";\n\nconst agentUrl =\n  process.env[\"LLAMAINDEX_AGENT_URL\"] ?? \"http://localhost:8000/run\";\n\nconst runtime = new CopilotRuntime({\n  agents: {\n    default: new LlamaIndexAgent({ url: agentUrl }),\n    support: new LlamaIndexAgent({ url: agentUrl }),\n  },\n  a2ui: {},\n});\n\nconst port = Number(process.env[\"PORT\"] ?? 8201);\n\ncreateServer(\n  createCopilotNodeListener({\n    runtime,\n    basePath: \"/api/copilotkit\",\n    cors: true,\n  }),\n).listen(port, () => {\n  console.log(\n    `Copilot Runtime listening at http://localhost:${port}/api/copilotkit`,\n  );\n  console.log(`LlamaIndex agent: ${agentUrl}`);\n});\n",
  "src/styles.css": "@import 'tailwindcss';\n\n/* Quickstart step \"Import the styles\". Self-contained — the chat renders\n   without any other CSS.\n   https://docs.copilotkit.ai/angular/llamaindex/quickstart */\n@import '@copilotkit/angular/styles.css';\n\n/* ------------------------------------------------------------------ */\n/* Harness chrome tokens                                              */\n/* `--line` and `--muted` are referenced by the A2UI guide's CSS below, */\n/* which does not define them itself.                                  */\n/* ------------------------------------------------------------------ */\n:root {\n  /* Surfaces */\n  --bg: #f4f6fa;\n  --surface: #ffffff;\n  --surface-sunken: #eef1f7;\n\n  /* Text — all AA or better on --surface */\n  --ink: #0d1526;\n  --ink-soft: #33415a;\n  --muted: #5c6a86;\n\n  /* Lines */\n  --line: #e0e5ee;\n  --line-strong: #c6cedd;\n\n  /* Accent */\n  --accent: #4f46e5;\n  --accent-hover: #4338ca;\n  --accent-soft: #eef0ff;\n  --accent-ink: #362fa8;\n\n  /* Code surface */\n  --code-bg: #0b1220;\n  --code-bar: #131c2f;\n  --code-ink: #dbe3f0;\n  --code-line: #24304a;\n}\n\nhtml,\nbody {\n  height: 100%;\n  margin: 0;\n  color: var(--ink);\n  background: var(--bg);\n  font-family:\n    'Inter',\n    -apple-system,\n    BlinkMacSystemFont,\n    'Segoe UI',\n    Roboto,\n    Helvetica,\n    Arial,\n    sans-serif;\n  -webkit-font-smoothing: antialiased;\n}\n\n/* Visible keyboard focus everywhere in the harness chrome (WCAG 2.4.7). */\na:focus-visible,\nbutton:focus-visible,\n[tabindex]:focus-visible {\n  outline: 2px solid var(--accent);\n  outline-offset: 2px;\n  border-radius: 0.375rem;\n}\n\n/* Inline code in prose — distinct from the dark code blocks. */\n.prose-inline-code,\np > code,\nli > code,\ntd > code {\n  padding: 0.1rem 0.35rem;\n  border: 1px solid var(--line);\n  border-radius: 0.3rem;\n  background: var(--surface-sunken);\n  color: var(--accent-ink);\n  font-size: 0.85em;\n}\n\n/* ------------------------------------------------------------------ */\n/* Code figures                                                        */\n/* ------------------------------------------------------------------ */\n.code-figure {\n  overflow: hidden;\n  border: 1px solid var(--code-line);\n  border-radius: 0.75rem;\n  background: var(--code-bg);\n  box-shadow: 0 12px 28px -22px rgb(11 18 32 / 0.65);\n}\n\n/* Quoted-from-docs samples read as secondary to the code that runs. */\n.code-figure--quoted {\n  border-style: dashed;\n  border-color: var(--line-strong);\n}\n\n.code-figure__bar {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.5rem 1rem;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0.5rem 0.85rem;\n  border-bottom: 1px solid var(--code-line);\n  background: var(--code-bar);\n}\n\n.code-figure__path {\n  color: #b9c6de;\n  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n  font-size: 0.72rem;\n  word-break: break-all;\n}\n\n.code-figure__meta {\n  display: flex;\n  flex-shrink: 0;\n  gap: 0.5rem;\n  align-items: center;\n}\n\n.code-figure__note {\n  color: #93a3c0;\n  font-size: 0.72rem;\n}\n\n.code-figure__lang,\n.code-figure__badge {\n  padding: 0.1rem 0.45rem;\n  border-radius: 999px;\n  background: #22304d;\n  color: #a9b8d6;\n  font-size: 0.65rem;\n  font-weight: 600;\n  letter-spacing: 0.02em;\n  text-transform: uppercase;\n}\n\n.code-figure__badge {\n  background: #3b2f18;\n  color: #e6c07b;\n}\n\n.code-figure__copy {\n  padding: 0.15rem 0.55rem;\n  border: 1px solid #2f3d5c;\n  border-radius: 0.35rem;\n  background: transparent;\n  color: #b9c6de;\n  font-size: 0.7rem;\n  font-weight: 600;\n  cursor: pointer;\n  transition: background 0.15s ease;\n}\n\n.code-figure__copy:hover {\n  background: #22304d;\n  color: #e6edf9;\n}\n\n.code-figure__pre {\n  max-height: 32rem;\n  margin: 0;\n  overflow: auto;\n  padding: 1rem;\n  color: var(--code-ink);\n  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n  font-size: 0.78rem;\n  line-height: 1.65;\n  tab-size: 2;\n}\n\n/* ------------------------------------------------------------------ */\n/* highlight.js theme — tuned for contrast on --code-bg                */\n/* ------------------------------------------------------------------ */\n.hljs-comment,\n.hljs-quote {\n  color: #8494b3;\n  font-style: italic;\n}\n\n.hljs-keyword,\n.hljs-selector-tag,\n.hljs-literal,\n.hljs-doctag {\n  color: #c4b5fd;\n}\n\n.hljs-string,\n.hljs-regexp,\n.hljs-addition {\n  color: #8ee7a5;\n}\n\n.hljs-number,\n.hljs-symbol,\n.hljs-bullet {\n  color: #fcd34d;\n}\n\n.hljs-title,\n.hljs-title.function_,\n.hljs-section {\n  color: #7dd3fc;\n}\n\n.hljs-title.class_,\n.hljs-type,\n.hljs-built_in,\n.hljs-class .hljs-title {\n  color: #fdba74;\n}\n\n.hljs-attr,\n.hljs-attribute,\n.hljs-property,\n.hljs-variable,\n.hljs-template-variable {\n  color: #f0abfc;\n}\n\n.hljs-name,\n.hljs-selector-id,\n.hljs-selector-class,\n.hljs-tag {\n  color: #fb7185;\n}\n\n.hljs-meta,\n.hljs-params,\n.hljs-punctuation {\n  color: #a5b4cd;\n}\n\n.hljs-deletion {\n  color: #fca5a5;\n}\n\n.hljs-emphasis {\n  font-style: italic;\n}\n\n.hljs-strong {\n  font-weight: 700;\n}\n\n/* ------------------------------------------------------------------ */\n/* Chat UI guide — \"Scope CSS changes\"                                 */\n/* https://docs.copilotkit.ai/angular/llamaindex/guides/chat-ui              */\n/* ------------------------------------------------------------------ */\n.support-chat .copilotKitUserMessage {\n  color: white;\n  background: #2563eb;\n  border-radius: 0.75rem;\n}\n\n.support-chat .copilotKitAssistantMessage {\n  padding: 0.75rem;\n  color: #172554;\n  background: #eff6ff;\n  border-radius: 0.75rem;\n}\n\n/* ------------------------------------------------------------------ */\n/* A2UI guide — \"Style rendered components\"                            */\n/* https://docs.copilotkit.ai/angular/llamaindex/guides/a2ui                 */\n/* ------------------------------------------------------------------ */\n.a2ui-row {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: stretch;\n  width: 100%;\n}\n\n.a2ui-row > * {\n  flex: 1 1 10rem;\n  min-width: 0;\n}\n\n.a2ui-column {\n  display: flex;\n  flex-direction: column;\n  width: 100%;\n}\n\n[data-testid='declarative-card'],\n.a2ui-chart-card,\n.a2ui-flight-card {\n  display: block;\n  padding: 1rem;\n  border: 1px solid var(--line);\n  border-radius: 0.9rem;\n  background: white;\n  box-shadow: 0 8px 22px -18px rgb(15 23 42 / 0.4);\n}\n\n.a2ui-metric {\n  display: grid;\n  min-width: 8rem;\n  gap: 0.25rem;\n}\n\n.a2ui-metric > span,\n.a2ui-metric > small {\n  color: var(--muted);\n  font-size: 0.75rem;\n}\n\n.a2ui-metric > strong {\n  font-size: 1.4rem;\n}\n\n.a2ui-status,\n.a2ui-airline {\n  display: inline-flex;\n  width: fit-content;\n  padding: 0.25rem 0.55rem;\n  border-radius: 999px;\n  background: #eef2ff;\n  font-size: 0.75rem;\n  font-weight: 700;\n}\n\n.a2ui-status-success {\n  background: #dcfce7;\n  color: #166534;\n}\n.a2ui-status-warning {\n  background: #fef3c7;\n  color: #92400e;\n}\n.a2ui-status-error {\n  background: #fee2e2;\n  color: #991b1b;\n}\n",
  "src/app/app.config.ts": "import {\n  ApplicationConfig,\n  provideBrowserGlobalErrorListeners,\n} from '@angular/core';\nimport { provideRouter, withInMemoryScrolling } from '@angular/router';\nimport { provideClientHydration } from '@angular/platform-browser';\nimport {\n  provideCopilotKit,\n  type SandboxFunction,\n} from '@copilotkit/angular';\nimport { z } from 'zod';\n\nimport { routes } from './app.routes';\n\n/**\n * Host function exposed to sandboxed Open Generative UI, verbatim from\n * https://docs.copilotkit.ai/angular/llamaindex/guides/frontend-tools-generative-ui\n */\nconst setDashboardFilter: SandboxFunction<{ filter: string }> = {\n  name: 'setDashboardFilter',\n  description: 'Set the active dashboard filter',\n  parameters: z.object({ filter: z.string() }),\n  handler: async ({ filter }) => {\n    sessionStorage.setItem('dashboard-filter', filter);\n    return { applied: filter };\n  },\n};\n\n\n/**\n * One provider at the application root, so a conversation started on any demo\n * route continues on every other route.\n *\n * `runtimeUrl` points at the Copilot Runtime from the quickstart — the\n * supported path, where the browser never talks to the LlamaIndex agent\n * directly. The `LlamaIndexAgent` binding that reaches the LlamaIndex AG-UI\n * endpoint lives server-side in frontend/server.ts.\n *\n * `a2ui.recovery` and `openGenerativeUI.sandboxFunctions` are the A2UI and\n * generative-UI guide options. No `a2ui.catalog` is set yet — supplying one is\n * what actually registers the render_a2ui renderer, so A2UI stays inert until\n * a catalog is added. See README known issues.\n */\nexport const appConfig: ApplicationConfig = {\n  providers: [\n    provideBrowserGlobalErrorListeners(),\n    provideRouter(\n      routes,\n      withInMemoryScrolling({ scrollPositionRestoration: 'top' }),\n    ),\n    provideClientHydration(),\n    provideCopilotKit({\n      runtimeUrl: 'http://localhost:8201/api/copilotkit',\n      a2ui: {\n        recovery: { showAfterMs: 2_000, showAfterAttempts: 2 },\n      },\n      openGenerativeUI: {\n        // `sandboxFunctions` is typed `SandboxFunction[]`, i.e.\n        // `SandboxFunction<Record<string, unknown>>[]`, so the guide's\n        // `SandboxFunction<{ filter: string }>` is not assignable to it as\n        // written. Cast at the array site, the same idiom the docs use for the\n        // equivalent `component` variance problem. See README known issues.\n        sandboxFunctions: [setDashboardFilter as unknown as SandboxFunction],\n      },\n    }),\n  ],\n};\n",
  "src/app/features/a2ui/a2ui-chat.component.ts": "/**\n * A2UI needs no component-level wiring: the runtime applies A2UIMiddleware\n * (`a2ui: {}` in frontend/server.ts) and, per the guide, \"on the frontend, the\n * A2UI renderer activates automatically. No extra configuration is needed.\"\n *\n * The recovery thresholds the guide prescribes are set once in\n * src/app/app.config.ts, and its catalog CSS lives in src/styles.css.\n * https://docs.copilotkit.ai/angular/llamaindex/guides/a2ui\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-a2ui-chat',\n  imports: [CopilotChat],\n  template: `\n    <div style=\"height: 100%\">\n      <copilot-chat />\n    </div>\n  `,\n})\nexport class A2uiChatComponent {}\n",
  "src/app/features/attachments/media-chat.component.ts": "/**\n * \"Enable attachments\", verbatim. Without `onUpload`, files are read as base64\n * and travel inline with the message.\n * https://docs.copilotkit.ai/angular/llamaindex/guides/threads-memory-attachments-headless\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat, type AttachmentsConfig } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-media-chat',\n  imports: [CopilotChat],\n  template: ` <copilot-chat [attachments]=\"attachments\" /> `,\n})\nexport class MediaChatComponent {\n  protected readonly attachments: AttachmentsConfig = {\n    enabled: true,\n    accept: 'image/*,application/pdf',\n    maxSize: 10 * 1024 * 1024,\n    onUploadFailed: (error) => {\n      console.error(error.reason, error.message);\n    },\n  };\n}\n",
  "src/app/features/chat-ui/chat-ui-demo.component.ts": "/**\n * Harness wrapper that mounts the guide's chat surfaces one at a time.\n *\n * The popup and the sidebar each get their own tab AND their own host\n * component. The guide declares both in a single component, but both render a\n * launcher at the same fixed coordinates, so mounting them together stacks two\n * launchers on one spot and the sidebar — rendered second — swallows every\n * click. The guide's combined component stays verbatim in\n * popup-sidebar.component.ts and is what the route page displays as source.\n *\n * Bindings on the split hosts are the guide's, unchanged.\n *\n * `.support-chat` is applied to the inline tab only. It is the scope class for\n * the guide's \"Scope CSS changes\" block, which repaints the message bubbles —\n * putting it on the shared host would tint the custom-message, popup, and\n * sidebar surfaces too, and each of those is meant to show its own default\n * styling.\n */\nimport { Component, signal } from '@angular/core';\n\nimport { CustomMessageChatComponent } from './custom-message-chat.component';\nimport { PopupOnlyComponent } from './popup-only.component';\nimport { SidebarOnlyComponent } from './sidebar-only.component';\nimport { SupportChatComponent } from './support-chat.component';\n\ntype Surface = 'inline' | 'custom-message' | 'popup' | 'sidebar';\n\n@Component({\n  selector: 'app-chat-ui-demo',\n  imports: [\n    SupportChatComponent,\n    CustomMessageChatComponent,\n    PopupOnlyComponent,\n    SidebarOnlyComponent,\n  ],\n  template: `\n    <div class=\"flex h-full flex-col gap-4 p-4\">\n      <div role=\"tablist\" aria-label=\"Chat surface\" class=\"flex flex-wrap gap-2\">\n        @for (tab of tabs; track tab.id) {\n          <button\n            type=\"button\"\n            role=\"tab\"\n            [attr.aria-selected]=\"surface() === tab.id\"\n            class=\"rounded-md border px-3 py-1.5 text-sm font-medium transition-colors\"\n            [class]=\"\n              surface() === tab.id\n                ? 'border-[var(--accent)] bg-[var(--accent)] text-white'\n                : 'border-[var(--line-strong)] bg-[var(--surface)] text-[var(--ink-soft)] hover:border-[var(--accent)] hover:text-[var(--accent-ink)]'\n            \"\n            (click)=\"surface.set(tab.id)\"\n          >\n            {{ tab.label }}\n          </button>\n        }\n      </div>\n\n      <div class=\"min-h-0 flex-1\">\n        @switch (surface()) {\n          @case ('inline') {\n            <!-- Scope class for the guide's CSS block — this tab only. -->\n            <div class=\"support-chat h-full\">\n              <app-support-chat />\n            </div>\n          }\n          @case ('custom-message') {\n            <div class=\"h-full\">\n              <app-custom-message-chat />\n            </div>\n          }\n          @case ('popup') {\n            <div class=\"space-y-3\">\n              <p class=\"text-sm text-[var(--ink-soft)]\">\n                <code>copilot-popup</code> opens from a floating launcher and\n                exposes a two-way <code>open</code> model, so the harness can\n                open it from here. It manages focus, closes on Escape, and\n                restores focus to the launcher.\n              </p>\n              <button\n                type=\"button\"\n                class=\"rounded-md border border-[var(--line-strong)] bg-[var(--surface)] px-3 py-1.5 text-sm font-medium text-[var(--ink-soft)] hover:border-[var(--accent)] hover:text-[var(--accent-ink)]\"\n                (click)=\"popupHost.popupOpen.set(!popupHost.popupOpen())\"\n              >\n                {{ popupHost.popupOpen() ? 'Close' : 'Open' }} popup\n              </button>\n              <app-popup-only #popupHost />\n            </div>\n          }\n          @case ('sidebar') {\n            <div class=\"space-y-3\">\n              <p class=\"text-sm text-[var(--ink-soft)]\">\n                <code>copilot-sidebar</code> is docked to the right at 480px.\n                Compact viewports render it as a modal even when\n                <code>mode</code> is <code>\"docked\"</code>, and only one open\n                docked sidebar can own the page margin at a time.\n              </p>\n              <button\n                type=\"button\"\n                class=\"rounded-md border border-[var(--line-strong)] bg-[var(--surface)] px-3 py-1.5 text-sm font-medium text-[var(--ink-soft)] hover:border-[var(--accent)] hover:text-[var(--accent-ink)]\"\n                (click)=\"sidebarHost.sidebarOpen.set(!sidebarHost.sidebarOpen())\"\n              >\n                {{ sidebarHost.sidebarOpen() ? 'Close' : 'Open' }} sidebar\n              </button>\n              <app-sidebar-only #sidebarHost />\n            </div>\n          }\n        }\n      </div>\n    </div>\n  `,\n})\nexport class ChatUiDemoComponent {\n  protected readonly surface = signal<Surface>('inline');\n  protected readonly tabs: ReadonlyArray<{ id: Surface; label: string }> = [\n    { id: 'inline', label: 'Inline chat' },\n    { id: 'custom-message', label: 'Custom assistant message' },\n    { id: 'popup', label: 'Popup' },\n    { id: 'sidebar', label: 'Sidebar' },\n  ];\n}\n",
  "src/app/features/chat-ui/custom-assistant-message.component.ts": "/**\n * \"Replace an assistant message\", verbatim.\n * https://docs.copilotkit.ai/angular/llamaindex/guides/chat-ui\n */\nimport { ChangeDetectionStrategy, Component, input } from '@angular/core';\n\ntype AssistantMessage = {\n  id: string;\n  role: 'assistant';\n  content?: string;\n};\n\n@Component({\n  selector: 'app-custom-assistant-message',\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  template: `\n    <article class=\"answer\">\n      <span class=\"answer__label\">Assistant</span>\n      <p>{{ message().content }}</p>\n    </article>\n  `,\n})\nexport class CustomAssistantMessageComponent {\n  readonly message = input.required<AssistantMessage>();\n}\n",
  "src/app/features/chat-ui/custom-message-chat.component.ts": "/**\n * The second `SupportChatComponent` from \"Replace an assistant message\",\n * verbatim except for the class name and selector — the guide gives two\n * different components the same name and selector, and both are mounted here.\n * https://docs.copilotkit.ai/angular/llamaindex/guides/chat-ui\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { CustomAssistantMessageComponent } from './custom-assistant-message.component';\n\n@Component({\n  selector: 'app-custom-message-chat',\n  imports: [CopilotChat],\n  template: `\n    <copilot-chat\n      [assistantMessageComponent]=\"assistantMessageComponent\"\n      assistantMessageClass=\"support-answer\"\n    />\n  `,\n})\nexport class CustomMessageChatComponent {\n  protected readonly assistantMessageComponent =\n    CustomAssistantMessageComponent;\n}\n",
  "src/app/features/chat-ui/popup-only.component.ts": "/**\n * The popup half of the guide's \"Use a popup or sidebar\" sample, on its own\n * host. Bindings are the guide's, unchanged.\n *\n * The guide declares `copilot-popup` and `copilot-sidebar` in one component.\n * Both render a launcher at the same fixed coordinates\n * (`right: max(1.5rem, …); bottom: max(1.5rem, …)`), so mounting them together\n * stacks two launchers on one spot and the sidebar — rendered second — takes\n * every click. Splitting them is what makes each surface separately testable;\n * the combined component is kept verbatim in popup-sidebar.component.ts and\n * shown as the source on the route page.\n *\n * https://docs.copilotkit.ai/angular/llamaindex/guides/chat-ui\n */\nimport { Component, signal } from '@angular/core';\nimport { CopilotPopup } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-popup-only',\n  imports: [CopilotPopup],\n  template: `\n    <copilot-popup\n      [(open)]=\"popupOpen\"\n      title=\"Support assistant\"\n      [clickOutsideToClose]=\"true\"\n    />\n  `,\n})\nexport class PopupOnlyComponent {\n  readonly popupOpen = signal(false);\n}\n",
  "src/app/features/chat-ui/popup-sidebar.component.ts": "/**\n * \"Use a popup or sidebar\", verbatim except for the class name and selector\n * (the guide mounts it as `AppComponent` / `app-root`).\n * https://docs.copilotkit.ai/angular/llamaindex/guides/chat-ui\n */\nimport { Component, signal } from '@angular/core';\nimport { CopilotPopup, CopilotSidebar } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-popup-sidebar',\n  imports: [CopilotPopup, CopilotSidebar],\n  template: `\n    <copilot-popup\n      [(open)]=\"popupOpen\"\n      title=\"Support assistant\"\n      [clickOutsideToClose]=\"true\"\n    />\n\n    <copilot-sidebar\n      [(open)]=\"sidebarOpen\"\n      mode=\"docked\"\n      position=\"right\"\n      title=\"Workspace assistant\"\n      [width]=\"480\"\n    />\n  `,\n})\nexport class PopupSidebarComponent {\n  readonly popupOpen = signal(false);\n  readonly sidebarOpen = signal(false);\n}\n",
  "src/app/features/chat-ui/sidebar-only.component.ts": "/**\n * The sidebar half of the guide's \"Use a popup or sidebar\" sample, on its own\n * host. Bindings are the guide's, unchanged.\n *\n * See popup-only.component.ts for why the guide's combined component is split\n * for the demo: both surfaces render a launcher at the same fixed coordinates.\n *\n * https://docs.copilotkit.ai/angular/llamaindex/guides/chat-ui\n */\nimport { Component, signal } from '@angular/core';\nimport { CopilotSidebar } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-sidebar-only',\n  imports: [CopilotSidebar],\n  template: `\n    <copilot-sidebar\n      [(open)]=\"sidebarOpen\"\n      mode=\"docked\"\n      position=\"right\"\n      title=\"Workspace assistant\"\n      [width]=\"480\"\n    />\n  `,\n})\nexport class SidebarOnlyComponent {\n  readonly sidebarOpen = signal(false);\n}\n",
  "src/app/features/chat-ui/support-chat.component.ts": "/**\n * \"Add an inline chat\", verbatim.\n * https://docs.copilotkit.ai/angular/llamaindex/guides/chat-ui\n *\n * `agentId=\"support\"` resolves because the runtime registers a `support` agent\n * alongside `default` (see frontend/server.ts).\n */\nimport { ChangeDetectionStrategy, Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-support-chat',\n  imports: [CopilotChat],\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  template: `\n    <section class=\"chat-shell\" aria-label=\"Support assistant\">\n      <copilot-chat agentId=\"support\" />\n    </section>\n  `,\n  styles: `\n    .chat-shell {\n      height: min(48rem, 80vh);\n      overflow: hidden;\n      border: 1px solid #dbe3eb;\n      border-radius: 1rem;\n    }\n  `,\n})\nexport class SupportChatComponent {}\n",
  "src/app/features/headless/headless-chat.component.ts": "/**\n * \"Build a headless chat\", verbatim. No CopilotKit chrome: the transcript and\n * composer are hand-written over `injectAgentStore`, and the run is driven\n * through `CopilotKitCore.runAgent`.\n * https://docs.copilotkit.ai/angular/llamaindex/guides/threads-memory-attachments-headless\n */\nimport { Component, inject, signal } from '@angular/core';\nimport { CopilotKit, injectAgentStore } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-headless-chat',\n  template: `\n    <div aria-live=\"polite\">\n      @for (message of store().messages(); track message.id) {\n        <article [attr.data-role]=\"message.role\">\n          {{ message.content }}\n        </article>\n      }\n      @if (store().isRunning()) {\n        <p>Agent is working…</p>\n      }\n    </div>\n\n    <textarea\n      aria-label=\"Message\"\n      [value]=\"draft()\"\n      (input)=\"updateDraft($event)\"\n    ></textarea>\n    <button\n      type=\"button\"\n      [disabled]=\"store().isRunning() || !draft().trim()\"\n      (click)=\"send()\"\n    >\n      Send\n    </button>\n  `,\n})\nexport class HeadlessChatComponent {\n  private readonly copilotKit = inject(CopilotKit);\n  readonly store = injectAgentStore('default');\n  readonly draft = signal('');\n\n  protected updateDraft(event: Event): void {\n    this.draft.set((event.target as HTMLTextAreaElement).value);\n  }\n\n  protected async send(): Promise<void> {\n    const content = this.draft().trim();\n    if (!content || this.store().isRunning()) return;\n\n    const agent = this.store().agent;\n    agent.addMessage({\n      id: crypto.randomUUID(),\n      role: 'user',\n      content,\n    });\n    this.draft.set('');\n    await this.copilotKit.core.runAgent({ agent });\n  }\n}\n",
  "src/app/features/hitl/approval-card.component.ts": "/**\n * \"Register a decision tool\" renderer, verbatim.\n * https://docs.copilotkit.ai/angular/llamaindex/guides/human-in-the-loop\n */\nimport { Component, input } from '@angular/core';\nimport {\n  type HumanInTheLoopToolCall,\n  type HumanInTheLoopToolRenderer,\n} from '@copilotkit/angular';\n\ntype ApprovalArgs = {\n  action: string;\n  reason: string;\n};\n\n@Component({\n  selector: 'app-approval-card',\n  template: `\n    @let call = toolCall();\n    <article>\n      <h3>Approve {{ call.args.action ?? \"this action\" }}?</h3>\n      <p>{{ call.args.reason }}</p>\n\n      @if (call.status !== \"complete\") {\n        <button type=\"button\" (click)=\"call.respond({ approved: true })\">\n          Approve\n        </button>\n        <button type=\"button\" (click)=\"call.respond({ approved: false })\">\n          Reject\n        </button>\n      }\n    </article>\n  `,\n})\nexport class ApprovalCardComponent\n  implements HumanInTheLoopToolRenderer<ApprovalArgs>\n{\n  readonly toolCall = input.required<HumanInTheLoopToolCall<ApprovalArgs>>();\n}\n",
  "src/app/features/hitl/approval-tools.service.ts": "/**\n * \"Register the tool from the component or service that owns the decision UI\",\n * verbatim. There is no handler — CopilotKit supplies one that waits for\n * `respond`, returns the decision to the agent, and continues the run.\n * https://docs.copilotkit.ai/angular/llamaindex/guides/human-in-the-loop\n */\nimport { Injectable } from '@angular/core';\nimport { registerHumanInTheLoop } from '@copilotkit/angular';\nimport { z } from 'zod';\n\nimport { ApprovalCardComponent } from './approval-card.component';\n\n@Injectable()\nexport class ApprovalToolsService {\n  constructor() {\n    registerHumanInTheLoop({\n      name: 'requestApproval',\n      description: 'Ask the user before a consequential action',\n      parameters: z.object({\n        action: z.string(),\n        reason: z.string(),\n      }),\n      component: ApprovalCardComponent,\n    });\n  }\n}\n",
  "src/app/features/hitl/hitl-chat.component.ts": "/**\n * Puts the guide's two human-in-the-loop paths side by side: the decision tool\n * (registered by ApprovalToolsService, rendered inside the chat's tool-call\n * flow) and the headless interrupt controller (rendered outside the chat).\n * https://docs.copilotkit.ai/angular/llamaindex/guides/human-in-the-loop\n *\n * Injecting ApprovalToolsService is what constructs it, and construction is\n * what performs the `registerHumanInTheLoop` call.\n */\nimport { Component, inject } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { ApprovalToolsService } from './approval-tools.service';\nimport { InterruptPanelComponent } from './interrupt-panel.component';\n\n@Component({\n  selector: 'app-hitl-chat',\n  imports: [CopilotChat, InterruptPanelComponent],\n  providers: [ApprovalToolsService],\n  template: `\n    <div style=\"display: flex; flex-direction: column; height: 100%\">\n      <app-interrupt-panel />\n      <div style=\"flex: 1; min-height: 0\">\n        <copilot-chat />\n      </div>\n    </div>\n  `,\n})\nexport class HitlChatComponent {\n  private readonly approvalTools = inject(ApprovalToolsService);\n}\n",
  "src/app/features/hitl/interrupt-panel.component.ts": "/**\n * \"Handle an interrupt\", verbatim. The controller is headless, so this panel\n * renders nothing until the backend emits an AG-UI interrupt.\n * https://docs.copilotkit.ai/angular/llamaindex/guides/human-in-the-loop\n */\nimport { Component } from '@angular/core';\nimport { injectInterrupt } from '@copilotkit/angular';\n\ntype ReviewRequest = {\n  title?: string;\n  choices?: Array<{ id: string; label: string }>;\n};\n\n@Component({\n  selector: 'app-interrupt-panel',\n  template: `\n    @if (controller.event(); as event) {\n      @let request = asReviewRequest(event.value);\n      <section aria-labelledby=\"review-title\">\n        <h2 id=\"review-title\">{{ request.title ?? \"Review required\" }}</h2>\n\n        @for (choice of request.choices ?? []; track choice.id) {\n          <button type=\"button\" (click)=\"resolve(choice.id)\">\n            {{ choice.label }}\n          </button>\n        }\n\n        <button type=\"button\" (click)=\"cancel()\">Cancel</button>\n      </section>\n    }\n\n    @if (controller.error()) {\n      <p role=\"alert\">The decision could not be submitted.</p>\n    }\n  `,\n})\nexport class InterruptPanelComponent {\n  protected readonly controller = injectInterrupt<ReviewRequest>({\n    agentId: 'default',\n  });\n\n  protected asReviewRequest(value: unknown): ReviewRequest {\n    return typeof value === 'object' && value !== null\n      ? (value as ReviewRequest)\n      : {};\n  }\n\n  protected resolve(choiceId: string): void {\n    this.controller.resolve({ choiceId }).catch(() => undefined);\n  }\n\n  protected cancel(): void {\n    this.controller.cancel().catch(() => undefined);\n  }\n}\n",
  "src/app/features/media/voice-chat.component.ts": "/**\n * \"Configure attachments\", verbatim: the guide's `MULTIMODAL_ATTACHMENTS`\n * config bound to the chat exactly as its `media-chat.component.html` snippet\n * shows. The microphone control needs no option — it is always present.\n * https://docs.copilotkit.ai/angular/llamaindex/guides/voice-multimodal\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat, type AttachmentsConfig } from '@copilotkit/angular';\n\nconst MULTIMODAL_ATTACHMENTS: AttachmentsConfig = {\n  enabled: true,\n  accept: 'image/*,application/pdf',\n  maxSize: 10 * 1024 * 1024,\n};\n\n@Component({\n  selector: 'app-voice-chat',\n  imports: [CopilotChat],\n  template: `\n    <div style=\"height: 100%\">\n      <copilot-chat [attachments]=\"multimodalAttachments\" />\n    </div>\n  `,\n})\nexport class VoiceChatComponent {\n  protected readonly multimodalAttachments = MULTIMODAL_ATTACHMENTS;\n}\n",
  "src/app/features/memory/memory-demo.component.ts": "/**\n * Harness wrapper mounting the guide's memory list beside a chat, so the\n * `isAvailable()` gate can be observed against a live runtime.\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { MemoryListComponent } from './memory-list.component';\n\n@Component({\n  selector: 'app-memory-demo',\n  imports: [CopilotChat, MemoryListComponent],\n  template: `\n    <div class=\"flex h-full gap-4 p-4\">\n      <section\n        class=\"w-80 shrink-0 overflow-y-auto rounded-lg border border-slate-200 bg-white p-4\"\n      >\n        <h2 class=\"mb-2 text-sm font-semibold text-slate-900\">\n          injectMemories\n        </h2>\n        <app-memory-list />\n      </section>\n      <div class=\"min-w-0 flex-1\">\n        <copilot-chat />\n      </div>\n    </div>\n  `,\n})\nexport class MemoryDemoComponent {}\n",
  "src/app/features/memory/memory-list.component.ts": "/**\n * \"Read and manage memory\", verbatim. The `isAvailable()` gate is the point of\n * the sample: a runtime may not provide the memory routes at all.\n * https://docs.copilotkit.ai/angular/llamaindex/guides/threads-memory-attachments-headless\n */\nimport { Component } from '@angular/core';\nimport { injectMemories } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-memory-list',\n  template: `\n    @if (!memory.isAvailable()) {\n      <p>Memory is not available for this runtime.</p>\n    } @else {\n      @for (item of memory.memories(); track item.id) {\n        <article>\n          <p>{{ item.content }}</p>\n          <button type=\"button\" (click)=\"remove(item.id)\">Forget</button>\n        </article>\n      }\n    }\n  `,\n})\nexport class MemoryListComponent {\n  readonly memory = injectMemories();\n\n  protected remove(id: string): void {\n    this.memory.removeMemory(id).catch(() => undefined);\n  }\n\n  protected addPreference(): void {\n    this.memory\n      .addMemory({\n        kind: 'operational',\n        content: 'Prefer concise status updates.',\n      })\n      .catch(() => undefined);\n  }\n}\n",
  "src/app/features/quickstart/quickstart-chat.ts": "/**\n * Quickstart step \"Add the chat UI\", verbatim.\n * https://docs.copilotkit.ai/angular/llamaindex/quickstart\n *\n * Only the selector and class name differ from the doc (which mounts this as\n * the app root); the template and imports are unchanged.\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-quickstart-chat',\n  imports: [CopilotChat],\n  template: `\n    <div style=\"height: 100vh\">\n      <copilot-chat />\n    </div>\n  `,\n})\nexport class QuickstartChat {}\n",
  "src/app/features/shared-state/account-context.component.ts": "/**\n * \"Send read-only application context\", verbatim. The accessor form keeps the\n * signal reads reactive, so changing the timezone re-registers the context.\n * https://docs.copilotkit.ai/angular/llamaindex/guides/shared-state\n */\nimport { Component, signal } from '@angular/core';\nimport { connectAgentContext } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-account-context',\n  template: `\n    <br>\n    <button type=\"button\" (click)=\"timezone.set('Europe/London')\">\n      Use London time\n    </button>\n  `,\n})\nexport class AccountContextComponent {\n  readonly userName = signal('Ada');\n  readonly timezone = signal('America/Los_Angeles');\n\n  constructor() {\n    connectAgentContext(() => ({\n      description: 'Current account and timezone',\n      value: JSON.stringify({\n        userName: this.userName(),\n        timezone: this.timezone(),\n      }),\n    }));\n  }\n}\n",
  "src/app/features/shared-state/selection-context.component.ts": "/**\n * \"Bind context in a template\", verbatim. The directive registers on first\n * render, so it must not be rendered before the context is complete.\n * https://docs.copilotkit.ai/angular/llamaindex/guides/shared-state\n */\nimport { Component, computed, signal } from '@angular/core';\nimport { CopilotKitAgentContext } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-selection-context',\n  imports: [CopilotKitAgentContext],\n  template: ` <div [copilotkitAgentContext]=\"selectionContext()\"></div> `,\n})\nexport class SelectionContextComponent {\n  readonly selectedId = signal('record-42');\n  readonly selectionContext = computed(() => ({\n    description: 'The record selected in the application',\n    value: this.selectedId(),\n  }));\n}\n",
  "src/app/features/shared-state/shared-state-chat.component.ts": "/**\n * Mounts the guide's three surfaces against one chat: the read/write state\n * panel, the accessor-based context, and the directive-based context.\n * https://docs.copilotkit.ai/angular/llamaindex/guides/shared-state\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { AccountContextComponent } from './account-context.component';\nimport { SelectionContextComponent } from './selection-context.component';\nimport { WorkspaceComponent } from './workspace.component';\n\n@Component({\n  selector: 'app-shared-state-chat',\n  imports: [\n    CopilotChat,\n    WorkspaceComponent,\n    AccountContextComponent,\n    SelectionContextComponent,\n  ],\n  template: `\n    <div style=\"display: flex; height: 100%; gap: 1rem\">\n      <div style=\"width: 20rem; overflow-y: auto; padding: 1rem\">\n        <app-workspace />\n        <app-account-context />\n        <app-selection-context />\n      </div>\n      <div style=\"flex: 1; min-width: 0\">\n        <copilot-chat />\n      </div>\n    </div>\n  `,\n})\nexport class SharedStateChatComponent {}\n",
  "src/app/features/shared-state/workspace.component.ts": "/**\n * \"Read agent state\", verbatim. Reads through `store().state()` so Angular\n * tracks changes; writes through the plain AG-UI agent at `store().agent`.\n * https://docs.copilotkit.ai/angular/llamaindex/guides/shared-state\n */\nimport { Component, computed } from '@angular/core';\nimport { injectAgentStore } from '@copilotkit/angular';\n\ntype WorkspaceState = {\n  notes: string[];\n  priority: 'low' | 'normal' | 'high';\n};\n\nconst EMPTY_STATE: WorkspaceState = {\n  notes: [],\n  priority: 'normal',\n};\n\n@Component({\n  selector: 'app-workspace',\n  template: `\n    <p>Priority: {{ state().priority }}</p>\n    <ul>\n      @for (note of state().notes; track note) {\n        <li>{{ note }}</li>\n      }\n    </ul>\n    <button type=\"button\" (click)=\"setPriority('high')\">\n      Mark high priority\n    </button>\n    <br>\n     <button type=\"button\" (click)=\"setPriority('low')\">\n      Mark low priority\n    </button>\n  `,\n})\nexport class WorkspaceComponent {\n  readonly store = injectAgentStore('default');\n  readonly state = computed(\n    () => (this.store().state() as WorkspaceState | undefined) ?? EMPTY_STATE,\n  );\n\n  protected setPriority(priority: WorkspaceState['priority']): void {\n    const agent = this.store().agent;\n    const current = (agent.state as WorkspaceState | undefined) ?? EMPTY_STATE;\n    agent.setState({ ...current, priority });\n  }\n}\n",
  "src/app/features/threads/conversations.component.ts": "/**\n * The drawer-plus-chat sample, verbatim. Both sit under one\n * `provideCopilotChatConfiguration`, which is what makes selection and\n * new-thread actions in the drawer update the chat.\n * https://docs.copilotkit.ai/angular/llamaindex/guides/threads-memory-attachments-headless\n */\nimport { Component } from '@angular/core';\nimport {\n  CopilotChat,\n  CopilotThreadsDrawer,\n  provideCopilotChatConfiguration,\n} from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-conversations',\n  imports: [CopilotChat, CopilotThreadsDrawer],\n  providers: [provideCopilotChatConfiguration({ agentId: 'support' })],\n  template: `\n    <copilot-threads-drawer agentId=\"support\" [limit]=\"20\" />\n    <copilot-chat />\n  `,\n})\nexport class ConversationsComponent {}\n",
  "src/app/features/threads/thread-list.component.ts": "/**\n * \"For a custom thread list, use injectThreads\", verbatim.\n * https://docs.copilotkit.ai/angular/llamaindex/guides/threads-memory-attachments-headless\n */\nimport { Component } from '@angular/core';\nimport { injectThreads } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-thread-list',\n  template: `\n    <button type=\"button\" (click)=\"threads.startNewThread()\">\n      New conversation\n    </button>\n\n    @if (threads.isLoading()) {\n      <p>Loading conversations…</p>\n    } @else {\n      @for (thread of threads.threads(); track thread.id) {\n        <button type=\"button\" (click)=\"select(thread.id)\">\n          {{ thread.name ?? \"Untitled conversation\" }}\n        </button>\n      }\n    }\n\n    @if (threads.listError()) {\n      <button type=\"button\" (click)=\"threads.refetchThreads()\">Retry</button>\n    }\n  `,\n})\nexport class ThreadListComponent {\n  readonly threads = injectThreads({\n    agentId: 'support',\n    limit: 20,\n  });\n\n  protected select(threadId: string): void {\n    // Store this id and bind it to CopilotChat's threadId input.\n    console.log(threadId);\n  }\n}\n",
  "src/app/features/threads/threads-demo.component.ts": "/**\n * Harness wrapper mounting both thread surfaces from the guide: the hand-built\n * list on `injectThreads`, and the drop-in drawer beside a chat.\n */\nimport { Component } from '@angular/core';\n\nimport { ConversationsComponent } from './conversations.component';\nimport { ThreadListComponent } from './thread-list.component';\n\n@Component({\n  selector: 'app-threads-demo',\n  imports: [ThreadListComponent, ConversationsComponent],\n  template: `\n    <div class=\"flex h-full flex-col gap-4 p-4\">\n      <section class=\"rounded-lg border border-slate-200 bg-white p-4\">\n        <h2 class=\"mb-2 text-sm font-semibold text-slate-900\">\n          Headless list — injectThreads\n        </h2>\n        <app-thread-list />\n      </section>\n\n      <section\n        class=\"flex min-h-0 flex-1 flex-col rounded-lg border border-slate-200 bg-white p-4\"\n      >\n        <h2 class=\"mb-2 text-sm font-semibold text-slate-900\">\n          CopilotThreadsDrawer + chat\n        </h2>\n        <div class=\"flex min-h-0 flex-1 gap-4\">\n          <app-conversations />\n        </div>\n      </section>\n    </div>\n  `,\n})\nexport class ThreadsDemoComponent {}\n",
  "src/app/features/tools/incident-card.component.ts": "/**\n * \"Let the agent display one of your components\", verbatim.\n * https://docs.copilotkit.ai/angular/llamaindex/guides/frontend-tools-generative-ui\n *\n * Two deviations from the published snippet, both mechanical:\n * `standalone: true` is dropped — it is the default on Angular v20+ and\n * frontend/AGENTS.md forbids setting it — and the two imports are narrowed to\n * `type` imports, matching weather-card.component.ts.\n *\n * Unlike WeatherCardComponent this renderer never reads `call.result`: a\n * display-only component has no application code behind it, so the tool\n * completes with an empty result and the args are the whole payload.\n */\nimport { Component, input } from '@angular/core';\nimport { type AngularToolCall, type ToolRenderer } from '@copilotkit/angular';\n\ntype IncidentArgs = { id: string; severity: string };\n\n@Component({\n  selector: 'app-incident-card',\n  template: `\n    @let call = toolCall();\n    @if (call.status === \"in-progress\") {\n      <p>Loading incident…</p>\n    } @else {\n      <article>\n        <strong>{{ call.args.id }}</strong>\n        <span>{{ call.args.severity }}</span>\n      </article>\n    }\n  `,\n})\nexport class IncidentCardComponent implements ToolRenderer<IncidentArgs> {\n  readonly toolCall = input.required<AngularToolCall<IncidentArgs>>();\n}\n",
  "src/app/features/tools/tool-feature-model.ts": "/**\n * The guide's `change_background` frontend tool.\n * https://docs.copilotkit.ai/angular/llamaindex/guides/frontend-tools-generative-ui\n *\n * `createBackgroundTool` is the guide's function, unchanged. Everything above\n * it is not in the guide: the snippet is quoted from the live Showcase without\n * its `BackgroundToolArgs` type, its `resolveGradient` helper, or its imports,\n * so those are defined here to make it runnable.\n */\nimport { type WritableSignal } from '@angular/core';\nimport { type FrontendToolConfig } from '@copilotkit/angular';\nimport { z } from 'zod';\n\n/** Arguments the agent may send to `change_background`. */\nexport type BackgroundToolArgs = {\n  background?: string;\n  color?: string;\n};\n\n/** Named presets so the agent can ask for a look without writing CSS. */\nconst GRADIENT_PRESETS: Record<string, string> = {\n  blue: 'linear-gradient(180deg, #0c4a6e 0%, #38bdf8 100%)',\n  violet: 'linear-gradient(180deg, #4c1d95 0%, #c084fc 100%)',\n  sunset: 'linear-gradient(180deg, #f97316 0%, #db2777 55%, #7c3aed 100%)',\n  forest: 'linear-gradient(180deg, #14532d 0%, #4ade80 100%)',\n  slate: 'linear-gradient(180deg, #0f172a 0%, #475569 100%)',\n};\n\nexport const DEFAULT_BACKGROUND = GRADIENT_PRESETS['slate'];\n\n/**\n * Accept a preset name, a bare CSS color, or a full gradient and always return\n * something safe to drop into a `background` style binding.\n */\nexport function resolveGradient(value: string | undefined): string {\n  const raw = value?.trim();\n  if (!raw) {\n    return DEFAULT_BACKGROUND;\n  }\n\n  const preset = GRADIENT_PRESETS[raw.toLowerCase()];\n  if (preset) {\n    return preset;\n  }\n\n  return raw.includes('gradient(')\n    ? raw\n    : `linear-gradient(180deg, ${raw} 0%, ${raw} 100%)`;\n}\n\n/** Create the frontend tool that applies a requested CSS gradient. */\nexport function createBackgroundTool(\n  background: WritableSignal<string>,\n): FrontendToolConfig<BackgroundToolArgs> {\n  return {\n    name: 'change_background',\n    description: 'Change the application background to a CSS gradient.',\n    parameters: z.object({\n      background: z.string().optional(),\n      color: z.string().optional(),\n    }),\n    handler: async (args) => {\n      const next = resolveGradient(args.background ?? args.color);\n      background.set(next);\n      return { background: next };\n    },\n  };\n}\n",
  "src/app/features/tools/tools-chat.component.ts": "/**\n * Mounts all three of the guide's frontend-tool paths against one chat.\n *\n * `registerRenderToolCall` — the tool runs on the server (the LlamaIndex\n * agent's weather tool) and the browser only renders its call, through\n * WeatherCardComponent.\n *\n * `registerComponent` — display only. `show_incident` has neither a handler\n * nor a tool on the agent: the frontend declares it, CopilotKit forwards it\n * over AG-UI, and the agent calls it purely to put IncidentCardComponent on\n * screen. Core inserts an empty tool result, so the turn completes without an\n * invented result being written into the thread.\n *\n * `registerFrontendTool` — the tool runs in the browser. `change_background`\n * has a handler and no component, so it renders nothing in chat; its result is\n * the page itself changing. The registration is removed when this injector is\n * destroyed.\n *\n * The guide's other `registerFrontendTool` sample is a second `getWeather`\n * that runs in the browser. It is not mounted: it would collide with the\n * server-side tool of the same name, and it calls an `/api/weather` endpoint\n * this repo does not serve.\n *\n * https://docs.copilotkit.ai/angular/llamaindex/guides/frontend-tools-generative-ui\n */\nimport { Component, signal } from '@angular/core';\nimport {\n  CopilotSidebar,\n  registerComponent,\n  registerFrontendTool,\n  registerRenderToolCall,\n} from '@copilotkit/angular';\nimport { z } from 'zod';\n\nimport {\n  DEFAULT_BACKGROUND,\n  createBackgroundTool,\n} from './tool-feature-model';\nimport { IncidentCardComponent } from './incident-card.component';\nimport { WeatherCardComponent } from './weather-card.component';\n\n@Component({\n  selector: 'app-tools-chat',\n  imports: [CopilotSidebar],\n  template: `\n    <div\n      style=\"height: 100%; display: flex; flex-direction: column; gap: 0.75rem; padding: 0.75rem; transition: background 400ms ease\"\n      [style.background]=\"background()\"\n    >\n        <copilot-sidebar />\n\n    </div>\n  `,\n})\nexport class ToolsChatComponent {\n  /** Written by the agent through the change_background handler. */\n  protected readonly background = signal(DEFAULT_BACKGROUND);\n\n  constructor() {\n    registerRenderToolCall({\n      name: 'getWeather',\n      args: z.object({ city: z.string() }),\n      component: WeatherCardComponent,\n    });\n\n    registerComponent({\n      name: 'show_incident',\n      description: 'Show one incident from the incident table.',\n      parameters: z.object({\n        id: z.string().describe('The incident id, such as INC-4711'),\n        severity: z.string().describe('One of sev1, sev2, sev3'),\n      }),\n      component: IncidentCardComponent,\n    });\n\n    registerFrontendTool(createBackgroundTool(this.background));\n  }\n}\n",
  "src/app/features/tools/weather-card.component.ts": "/**\n * \"Render a tool result\", verbatim.\n * https://docs.copilotkit.ai/angular/llamaindex/guides/frontend-tools-generative-ui\n */\nimport { Component, input } from '@angular/core';\nimport { type AngularToolCall, type ToolRenderer } from '@copilotkit/angular';\n\ntype WeatherArgs = { city: string };\n\n@Component({\n  selector: 'app-weather-card',\n  template: `\n    @let call = toolCall();\n    @if (call.status === \"complete\") {\n      <article>\n        <strong>{{ call.args.city }}</strong>\n        <p>{{ call.result }}</p>\n      </article>\n    } @else {\n      <p>Loading weather for {{ call.args.city ?? \"…\" }}</p>\n    }\n    <p>Tool Call done </p>\n  `,\n})\nexport class WeatherCardComponent implements ToolRenderer<WeatherArgs> {\n  readonly toolCall = input.required<AngularToolCall<WeatherArgs>>();\n}\n",
  "src/app/features/webmcp/order-search.component.ts": "/**\n * \"Angular frontend tool\", verbatim — everything down to the DOC GAP FILL\n * marker is the page's `src/app/order-search.component.ts` sample, unchanged\n * (including its `standalone: true`).\n * https://docs.copilotkit.ai/angular/llamaindex/webmcp\n *\n * Mounted once, the tool is visible to two callers through the same handler:\n * the CopilotKit agent (as an ordinary frontend tool forwarded over AG-UI) and,\n * in a WebMCP-capable browser, any browser agent reading\n * `document.modelContext`.\n */\nimport { Component } from \"@angular/core\";\nimport { registerFrontendTool } from \"@copilotkit/angular\";\nimport { z } from \"zod\";\n\n@Component({\n  selector: \"app-order-search\",\n  standalone: true,\n  template: \"\",\n})\nexport class OrderSearchComponent {\n  constructor() {\n    registerFrontendTool({\n      name: \"searchOrders\",\n      description: \"Search the signed-in user's orders by status\",\n      parameters: z.object({\n        status: z.enum([\"open\", \"shipped\", \"delivered\"]),\n      }),\n      handler: async ({ status }) => {\n        const orders = await searchOrders(status);\n        return JSON.stringify(orders);\n      },\n      webmcp: {\n        annotations: {\n          readOnlyHint: true,\n        },\n      },\n    });\n  }\n}\n\n// ---------------------------------------------------------------------------\n// DOC GAP FILL — not on the page.\n//\n// Both samples on the page call `searchOrders(status)` and neither defines it;\n// in the doc it stands for \"your app's existing order lookup\". This stub is\n// the smallest thing that lets the sample compile and return a result a\n// caller can check: a fixed in-memory list, filtered by status. It reads\n// only, which keeps the sample's `readOnlyHint: true` honest.\n// ---------------------------------------------------------------------------\ntype OrderStatus = \"open\" | \"shipped\" | \"delivered\";\n\nconst SAMPLE_ORDERS: { id: string; item: string; status: OrderStatus }[] = [\n  { id: \"ORD-1001\", item: \"Desk lamp\", status: \"open\" },\n  { id: \"ORD-1002\", item: \"Monitor arm\", status: \"shipped\" },\n  { id: \"ORD-1003\", item: \"Keyboard\", status: \"delivered\" },\n  { id: \"ORD-1004\", item: \"USB-C hub\", status: \"open\" },\n];\n\nasync function searchOrders(status: OrderStatus) {\n  return SAMPLE_ORDERS.filter((order) => order.status === status);\n}\n",
  "src/app/features/webmcp/webmcp-chat.component.ts": "/**\n * Mounts the guide's WebMCP tool beside a chat, so both of its callers can be\n * exercised from one page.\n * https://docs.copilotkit.ai/angular/llamaindex/webmcp\n *\n * - `<app-order-search />` is the page's component. It renders nothing; its\n *   constructor registers `searchOrders` with `webmcp` enabled.\n * - `<copilot-chat />` drives the `default` agent, which receives\n *   `searchOrders` as an ordinary frontend tool. This path works in any\n *   browser.\n * - The panel checks for `document.modelContext` — step 3 of the page's\n *   \"Test the complete path\". When it is missing, CopilotKit registers nothing\n *   with WebMCP and the browser-agent path cannot be tested here.\n */\nimport { Component, afterNextRender, signal } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { OrderSearchComponent } from './order-search.component';\n\n@Component({\n  selector: 'app-webmcp-chat',\n  imports: [CopilotChat, OrderSearchComponent],\n  template: `\n    <app-order-search />\n    <div style=\"display: flex; flex-direction: column; height: 100%\">\n      <p\n        role=\"status\"\n        style=\"margin: 0; padding: 0.6rem 1rem; font-size: 0.85rem; border-bottom: 1px solid #e2e8f0\"\n        [style.background]=\"modelContext() ? '#ecfdf5' : '#fffbeb'\"\n      >\n        <code>document.modelContext</code>:\n        @switch (modelContext()) {\n          @case (true) {\n            <strong>available</strong> — <code>searchOrders</code> is\n            registered with WebMCP. Inspect it with Chrome's Model Context Tool\n            Inspector.\n          }\n          @case (false) {\n            <strong>not available</strong> — WebMCP registration is a no-op in\n            this browser. The chat path below still works.\n          }\n          @default {\n            checking…\n          }\n        }\n      </p>\n      <div style=\"flex: 1; min-height: 0\">\n        <copilot-chat />\n      </div>\n    </div>\n  `,\n})\nexport class WebmcpChatComponent {\n  /** `null` until the browser has rendered — `document` does not exist under SSR. */\n  protected readonly modelContext = signal<boolean | null>(null);\n\n  constructor() {\n    afterNextRender(() => {\n      this.modelContext.set('modelContext' in document);\n    });\n  }\n}\n",
  "server.ts": "/**\r\n * Copilot Runtime for this harness.\r\n *\r\n * Shape comes from the Angular quickstart's Node runtime server, with the\r\n * agent swapped for the LlamaIndex backend in `../backend`.\r\n *\r\n * That backend exposes a plain AG-UI endpoint —\r\n * `app.include_router(get_ag_ui_workflow_router(...))` in backend/main.py\r\n * mounts a single `POST /run` that streams AG-UI events over SSE.\r\n *\r\n * `LlamaIndexAgent` from `@ag-ui/llamaindex` is the binding for that endpoint.\r\n * It is an `HttpAgent` subclass that pins the AG-UI protocol version the\r\n * LlamaIndex workflow router speaks, and substitutes a placeholder body for\r\n * empty tool results, which that router rejects.\r\n *\r\n * `default` and `support` resolve to the same LlamaIndex process.\r\n * `support` exists so the doc snippets that use `agentId=\"support\"` (Chat UI,\r\n * Threads) run verbatim.\r\n *\r\n * `subagents` is a separate LlamaIndex router — the supervisor from the\r\n * Sub-Agents page — mounted by backend/main.py at `/subagents`, so its\r\n * `delegations` state never mixes with the `default` agent's.\r\n *\r\n * `a2ui: {}` enables A2UIMiddleware for every registered agent, per\r\n * https://docs.copilotkit.ai/angular/llamaindex/guides/a2ui\r\n * — it is a runtime-side middleware and is independent of which agent binding\r\n * is used.\r\n *\r\n * Ports: backend/main.py binds 8000, so the runtime sits on 8201. Override\r\n * either side with PORT / LLAMAINDEX_AGENT_URL.\r\n */\r\nimport { createServer } from \"node:http\";\r\nimport { CopilotRuntime } from \"@copilotkit/runtime/v2\";\r\nimport { createCopilotNodeListener } from \"@copilotkit/runtime/v2/node\";\r\nimport { LlamaIndexAgent } from \"@ag-ui/llamaindex\";\r\n\r\nconst agentUrl =\r\n  process.env[\"LLAMAINDEX_AGENT_URL\"] ?? \"http://localhost:8000/run\";\r\n\r\n// The Sub-Agents supervisor, mounted by backend/main.py at `/subagents`.\r\nconst subagentsUrl =\r\n  process.env[\"LLAMAINDEX_SUBAGENTS_URL\"] ??\r\n  \"http://localhost:8000/subagents/run\";\r\n\r\nconst runtime = new CopilotRuntime({\r\n  agents: {\r\n    default: new LlamaIndexAgent({ url: agentUrl }),\r\n    support: new LlamaIndexAgent({ url: agentUrl }),\r\n    subagents: new LlamaIndexAgent({ url: subagentsUrl }),\r\n  },\r\n  a2ui: {},\r\n});\r\n\r\nconst port = Number(process.env[\"PORT\"] ?? 8201);\r\n\r\ncreateServer(\r\n  createCopilotNodeListener({\r\n    runtime,\r\n    basePath: \"/api/copilotkit\",\r\n    cors: true,\r\n  }),\r\n).listen(port, () => {\r\n  console.log(\r\n    `Copilot Runtime listening at http://localhost:${port}/api/copilotkit`,\r\n  );\r\n  console.log(`LlamaIndex agent: ${agentUrl}`);\r\n});\r\n",
  "src/styles.css": "@import 'tailwindcss';\r\n\r\n/* Quickstart step \"Import the styles\". Self-contained — the chat renders\r\n   without any other CSS.\r\n   https://docs.copilotkit.ai/angular/llamaindex/quickstart */\r\n@import '@copilotkit/angular/styles.css';\r\n\r\n/* ------------------------------------------------------------------ */\r\n/* Harness chrome tokens                                              */\r\n/* `--line` and `--muted` are referenced by the A2UI guide's CSS below, */\r\n/* which does not define them itself.                                  */\r\n/* ------------------------------------------------------------------ */\r\n:root {\r\n  /* Surfaces */\r\n  --bg: #f4f6fa;\r\n  --surface: #ffffff;\r\n  --surface-sunken: #eef1f7;\r\n\r\n  /* Text — all AA or better on --surface */\r\n  --ink: #0d1526;\r\n  --ink-soft: #33415a;\r\n  --muted: #5c6a86;\r\n\r\n  /* Lines */\r\n  --line: #e0e5ee;\r\n  --line-strong: #c6cedd;\r\n\r\n  /* Accent */\r\n  --accent: #4f46e5;\r\n  --accent-hover: #4338ca;\r\n  --accent-soft: #eef0ff;\r\n  --accent-ink: #362fa8;\r\n\r\n  /* Code surface */\r\n  --code-bg: #0b1220;\r\n  --code-bar: #131c2f;\r\n  --code-ink: #dbe3f0;\r\n  --code-line: #24304a;\r\n}\r\n\r\nhtml,\r\nbody {\r\n  height: 100%;\r\n  margin: 0;\r\n  color: var(--ink);\r\n  background: var(--bg);\r\n  font-family:\r\n    'Inter',\r\n    -apple-system,\r\n    BlinkMacSystemFont,\r\n    'Segoe UI',\r\n    Roboto,\r\n    Helvetica,\r\n    Arial,\r\n    sans-serif;\r\n  -webkit-font-smoothing: antialiased;\r\n}\r\n\r\n/* Visible keyboard focus everywhere in the harness chrome (WCAG 2.4.7). */\r\na:focus-visible,\r\nbutton:focus-visible,\r\n[tabindex]:focus-visible {\r\n  outline: 2px solid var(--accent);\r\n  outline-offset: 2px;\r\n  border-radius: 0.375rem;\r\n}\r\n\r\n/* Inline code in prose — distinct from the dark code blocks. */\r\n.prose-inline-code,\r\np > code,\r\nli > code,\r\ntd > code {\r\n  padding: 0.1rem 0.35rem;\r\n  border: 1px solid var(--line);\r\n  border-radius: 0.3rem;\r\n  background: var(--surface-sunken);\r\n  color: var(--accent-ink);\r\n  font-size: 0.85em;\r\n}\r\n\r\n/* ------------------------------------------------------------------ */\r\n/* Code figures                                                        */\r\n/* ------------------------------------------------------------------ */\r\n.code-figure {\r\n  overflow: hidden;\r\n  border: 1px solid var(--code-line);\r\n  border-radius: 0.75rem;\r\n  background: var(--code-bg);\r\n  box-shadow: 0 12px 28px -22px rgb(11 18 32 / 0.65);\r\n}\r\n\r\n/* Quoted-from-docs samples read as secondary to the code that runs. */\r\n.code-figure--quoted {\r\n  border-style: dashed;\r\n  border-color: var(--line-strong);\r\n}\r\n\r\n.code-figure__bar {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: 0.5rem 1rem;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  padding: 0.5rem 0.85rem;\r\n  border-bottom: 1px solid var(--code-line);\r\n  background: var(--code-bar);\r\n}\r\n\r\n.code-figure__path {\r\n  color: #b9c6de;\r\n  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\r\n  font-size: 0.72rem;\r\n  word-break: break-all;\r\n}\r\n\r\n.code-figure__meta {\r\n  display: flex;\r\n  flex-shrink: 0;\r\n  gap: 0.5rem;\r\n  align-items: center;\r\n}\r\n\r\n.code-figure__note {\r\n  color: #93a3c0;\r\n  font-size: 0.72rem;\r\n}\r\n\r\n.code-figure__lang,\r\n.code-figure__badge {\r\n  padding: 0.1rem 0.45rem;\r\n  border-radius: 999px;\r\n  background: #22304d;\r\n  color: #a9b8d6;\r\n  font-size: 0.65rem;\r\n  font-weight: 600;\r\n  letter-spacing: 0.02em;\r\n  text-transform: uppercase;\r\n}\r\n\r\n.code-figure__badge {\r\n  background: #3b2f18;\r\n  color: #e6c07b;\r\n}\r\n\r\n.code-figure__copy {\r\n  padding: 0.15rem 0.55rem;\r\n  border: 1px solid #2f3d5c;\r\n  border-radius: 0.35rem;\r\n  background: transparent;\r\n  color: #b9c6de;\r\n  font-size: 0.7rem;\r\n  font-weight: 600;\r\n  cursor: pointer;\r\n  transition: background 0.15s ease;\r\n}\r\n\r\n.code-figure__copy:hover {\r\n  background: #22304d;\r\n  color: #e6edf9;\r\n}\r\n\r\n.code-figure__pre {\r\n  max-height: 32rem;\r\n  margin: 0;\r\n  overflow: auto;\r\n  padding: 1rem;\r\n  color: var(--code-ink);\r\n  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\r\n  font-size: 0.78rem;\r\n  line-height: 1.65;\r\n  tab-size: 2;\r\n}\r\n\r\n/* ------------------------------------------------------------------ */\r\n/* highlight.js theme — tuned for contrast on --code-bg                */\r\n/* ------------------------------------------------------------------ */\r\n.hljs-comment,\r\n.hljs-quote {\r\n  color: #8494b3;\r\n  font-style: italic;\r\n}\r\n\r\n.hljs-keyword,\r\n.hljs-selector-tag,\r\n.hljs-literal,\r\n.hljs-doctag {\r\n  color: #c4b5fd;\r\n}\r\n\r\n.hljs-string,\r\n.hljs-regexp,\r\n.hljs-addition {\r\n  color: #8ee7a5;\r\n}\r\n\r\n.hljs-number,\r\n.hljs-symbol,\r\n.hljs-bullet {\r\n  color: #fcd34d;\r\n}\r\n\r\n.hljs-title,\r\n.hljs-title.function_,\r\n.hljs-section {\r\n  color: #7dd3fc;\r\n}\r\n\r\n.hljs-title.class_,\r\n.hljs-type,\r\n.hljs-built_in,\r\n.hljs-class .hljs-title {\r\n  color: #fdba74;\r\n}\r\n\r\n.hljs-attr,\r\n.hljs-attribute,\r\n.hljs-property,\r\n.hljs-variable,\r\n.hljs-template-variable {\r\n  color: #f0abfc;\r\n}\r\n\r\n.hljs-name,\r\n.hljs-selector-id,\r\n.hljs-selector-class,\r\n.hljs-tag {\r\n  color: #fb7185;\r\n}\r\n\r\n.hljs-meta,\r\n.hljs-params,\r\n.hljs-punctuation {\r\n  color: #a5b4cd;\r\n}\r\n\r\n.hljs-deletion {\r\n  color: #fca5a5;\r\n}\r\n\r\n.hljs-emphasis {\r\n  font-style: italic;\r\n}\r\n\r\n.hljs-strong {\r\n  font-weight: 700;\r\n}\r\n\r\n/* ------------------------------------------------------------------ */\r\n/* Chat UI guide — \"Scope CSS changes\"                                 */\r\n/* https://docs.copilotkit.ai/angular/llamaindex/guides/chat-ui              */\r\n/* ------------------------------------------------------------------ */\r\n.support-chat .copilotKitUserMessage {\r\n  color: white;\r\n  background: #2563eb;\r\n  border-radius: 0.75rem;\r\n}\r\n\r\n.support-chat .copilotKitAssistantMessage {\r\n  padding: 0.75rem;\r\n  color: #172554;\r\n  background: #eff6ff;\r\n  border-radius: 0.75rem;\r\n}\r\n\r\n/* ------------------------------------------------------------------ */\r\n/* A2UI guide — \"Style rendered components\"                            */\r\n/* https://docs.copilotkit.ai/angular/llamaindex/guides/a2ui                 */\r\n/* ------------------------------------------------------------------ */\r\n.a2ui-row {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  align-items: stretch;\r\n  width: 100%;\r\n}\r\n\r\n.a2ui-row > * {\r\n  flex: 1 1 10rem;\r\n  min-width: 0;\r\n}\r\n\r\n.a2ui-column {\r\n  display: flex;\r\n  flex-direction: column;\r\n  width: 100%;\r\n}\r\n\r\n[data-testid='declarative-card'],\r\n.a2ui-chart-card,\r\n.a2ui-flight-card {\r\n  display: block;\r\n  padding: 1rem;\r\n  border: 1px solid var(--line);\r\n  border-radius: 0.9rem;\r\n  background: white;\r\n  box-shadow: 0 8px 22px -18px rgb(15 23 42 / 0.4);\r\n}\r\n\r\n.a2ui-metric {\r\n  display: grid;\r\n  min-width: 8rem;\r\n  gap: 0.25rem;\r\n}\r\n\r\n.a2ui-metric > span,\r\n.a2ui-metric > small {\r\n  color: var(--muted);\r\n  font-size: 0.75rem;\r\n}\r\n\r\n.a2ui-metric > strong {\r\n  font-size: 1.4rem;\r\n}\r\n\r\n.a2ui-status,\r\n.a2ui-airline {\r\n  display: inline-flex;\r\n  width: fit-content;\r\n  padding: 0.25rem 0.55rem;\r\n  border-radius: 999px;\r\n  background: #eef2ff;\r\n  font-size: 0.75rem;\r\n  font-weight: 700;\r\n}\r\n\r\n.a2ui-status-success {\r\n  background: #dcfce7;\r\n  color: #166534;\r\n}\r\n.a2ui-status-warning {\r\n  background: #fef3c7;\r\n  color: #92400e;\r\n}\r\n.a2ui-status-error {\r\n  background: #fee2e2;\r\n  color: #991b1b;\r\n}\r\n",
  "src/app/app.config.ts": "import {\r\n  ApplicationConfig,\r\n  provideBrowserGlobalErrorListeners,\r\n} from '@angular/core';\r\nimport { provideRouter, withInMemoryScrolling } from '@angular/router';\r\nimport { provideClientHydration } from '@angular/platform-browser';\r\nimport {\r\n  provideCopilotKit,\r\n  type SandboxFunction,\r\n} from '@copilotkit/angular';\r\nimport { z } from 'zod';\r\n\r\nimport { routes } from './app.routes';\r\n\r\n/**\r\n * Host function exposed to sandboxed Open Generative UI, verbatim from\r\n * https://docs.copilotkit.ai/angular/llamaindex/guides/frontend-tools-generative-ui\r\n */\r\nconst setDashboardFilter: SandboxFunction<{ filter: string }> = {\r\n  name: 'setDashboardFilter',\r\n  description: 'Set the active dashboard filter',\r\n  parameters: z.object({ filter: z.string() }),\r\n  handler: async ({ filter }) => {\r\n    sessionStorage.setItem('dashboard-filter', filter);\r\n    return { applied: filter };\r\n  },\r\n};\r\n\r\n\r\n/**\r\n * One provider at the application root, so a conversation started on any demo\r\n * route continues on every other route.\r\n *\r\n * `runtimeUrl` points at the Copilot Runtime from the quickstart — the\r\n * supported path, where the browser never talks to the LlamaIndex agent\r\n * directly. The `LlamaIndexAgent` binding that reaches the LlamaIndex AG-UI\r\n * endpoint lives server-side in frontend/server.ts.\r\n *\r\n * `a2ui.recovery` and `openGenerativeUI.sandboxFunctions` are the A2UI and\r\n * generative-UI guide options. No `a2ui.catalog` is set yet — supplying one is\r\n * what actually registers the render_a2ui renderer, so A2UI stays inert until\r\n * a catalog is added. See README known issues.\r\n */\r\nexport const appConfig: ApplicationConfig = {\r\n  providers: [\r\n    provideBrowserGlobalErrorListeners(),\r\n    provideRouter(\r\n      routes,\r\n      withInMemoryScrolling({ scrollPositionRestoration: 'top' }),\r\n    ),\r\n    provideClientHydration(),\r\n    provideCopilotKit({\r\n      runtimeUrl: 'http://localhost:8201/api/copilotkit',\r\n      a2ui: {\r\n        recovery: { showAfterMs: 2_000, showAfterAttempts: 2 },\r\n      },\r\n      openGenerativeUI: {\r\n        // `sandboxFunctions` is typed `SandboxFunction[]`, i.e.\r\n        // `SandboxFunction<Record<string, unknown>>[]`, so the guide's\r\n        // `SandboxFunction<{ filter: string }>` is not assignable to it as\r\n        // written. Cast at the array site, the same idiom the docs use for the\r\n        // equivalent `component` variance problem. See README known issues.\r\n        sandboxFunctions: [setDashboardFilter as unknown as SandboxFunction],\r\n      },\r\n    }),\r\n  ],\r\n};\r\n",
  "src/app/features/a2ui/a2ui-chat.component.ts": "/**\r\n * A2UI needs no component-level wiring: the runtime applies A2UIMiddleware\r\n * (`a2ui: {}` in frontend/server.ts) and, per the guide, \"on the frontend, the\r\n * A2UI renderer activates automatically. No extra configuration is needed.\"\r\n *\r\n * The recovery thresholds the guide prescribes are set once in\r\n * src/app/app.config.ts, and its catalog CSS lives in src/styles.css.\r\n * https://docs.copilotkit.ai/angular/llamaindex/guides/a2ui\r\n */\r\nimport { Component } from '@angular/core';\r\nimport { CopilotChat } from '@copilotkit/angular';\r\n\r\n@Component({\r\n  selector: 'app-a2ui-chat',\r\n  imports: [CopilotChat],\r\n  template: `\r\n    <div style=\"height: 100%\">\r\n      <copilot-chat />\r\n    </div>\r\n  `,\r\n})\r\nexport class A2uiChatComponent {}\r\n",
  "src/app/features/attachments/media-chat.component.ts": "/**\r\n * \"Enable attachments\", verbatim. Without `onUpload`, files are read as base64\r\n * and travel inline with the message.\r\n * https://docs.copilotkit.ai/angular/llamaindex/guides/threads-memory-attachments-headless\r\n */\r\nimport { Component } from '@angular/core';\r\nimport { CopilotChat, type AttachmentsConfig } from '@copilotkit/angular';\r\n\r\n@Component({\r\n  selector: 'app-media-chat',\r\n  imports: [CopilotChat],\r\n  template: ` <copilot-chat [attachments]=\"attachments\" /> `,\r\n})\r\nexport class MediaChatComponent {\r\n  protected readonly attachments: AttachmentsConfig = {\r\n    enabled: true,\r\n    accept: 'image/*,application/pdf',\r\n    maxSize: 10 * 1024 * 1024,\r\n    onUploadFailed: (error) => {\r\n      console.error(error.reason, error.message);\r\n    },\r\n  };\r\n}\r\n",
  "src/app/features/chat-ui/chat-ui-demo.component.ts": "/**\r\n * Harness wrapper that mounts the guide's chat surfaces one at a time.\r\n *\r\n * The popup and the sidebar each get their own tab AND their own host\r\n * component. The guide declares both in a single component, but both render a\r\n * launcher at the same fixed coordinates, so mounting them together stacks two\r\n * launchers on one spot and the sidebar — rendered second — swallows every\r\n * click. The guide's combined component stays verbatim in\r\n * popup-sidebar.component.ts and is what the route page displays as source.\r\n *\r\n * Bindings on the split hosts are the guide's, unchanged.\r\n *\r\n * `.support-chat` is applied to the inline tab only. It is the scope class for\r\n * the guide's \"Scope CSS changes\" block, which repaints the message bubbles —\r\n * putting it on the shared host would tint the custom-message, popup, and\r\n * sidebar surfaces too, and each of those is meant to show its own default\r\n * styling.\r\n */\r\nimport { Component, signal } from '@angular/core';\r\n\r\nimport { CustomMessageChatComponent } from './custom-message-chat.component';\r\nimport { PopupOnlyComponent } from './popup-only.component';\r\nimport { SidebarOnlyComponent } from './sidebar-only.component';\r\nimport { SupportChatComponent } from './support-chat.component';\r\n\r\ntype Surface = 'inline' | 'custom-message' | 'popup' | 'sidebar';\r\n\r\n@Component({\r\n  selector: 'app-chat-ui-demo',\r\n  imports: [\r\n    SupportChatComponent,\r\n    CustomMessageChatComponent,\r\n    PopupOnlyComponent,\r\n    SidebarOnlyComponent,\r\n  ],\r\n  template: `\r\n    <div class=\"flex h-full flex-col gap-4 p-4\">\r\n      <div role=\"tablist\" aria-label=\"Chat surface\" class=\"flex flex-wrap gap-2\">\r\n        @for (tab of tabs; track tab.id) {\r\n          <button\r\n            type=\"button\"\r\n            role=\"tab\"\r\n            [attr.aria-selected]=\"surface() === tab.id\"\r\n            class=\"rounded-md border px-3 py-1.5 text-sm font-medium transition-colors\"\r\n            [class]=\"\r\n              surface() === tab.id\r\n                ? 'border-[var(--accent)] bg-[var(--accent)] text-white'\r\n                : 'border-[var(--line-strong)] bg-[var(--surface)] text-[var(--ink-soft)] hover:border-[var(--accent)] hover:text-[var(--accent-ink)]'\r\n            \"\r\n            (click)=\"surface.set(tab.id)\"\r\n          >\r\n            {{ tab.label }}\r\n          </button>\r\n        }\r\n      </div>\r\n\r\n      <div class=\"min-h-0 flex-1\">\r\n        @switch (surface()) {\r\n          @case ('inline') {\r\n            <!-- Scope class for the guide's CSS block — this tab only. -->\r\n            <div class=\"support-chat h-full\">\r\n              <app-support-chat />\r\n            </div>\r\n          }\r\n          @case ('custom-message') {\r\n            <div class=\"h-full\">\r\n              <app-custom-message-chat />\r\n            </div>\r\n          }\r\n          @case ('popup') {\r\n            <div class=\"space-y-3\">\r\n              <p class=\"text-sm text-[var(--ink-soft)]\">\r\n                <code>copilot-popup</code> opens from a floating launcher and\r\n                exposes a two-way <code>open</code> model, so the harness can\r\n                open it from here. It manages focus, closes on Escape, and\r\n                restores focus to the launcher.\r\n              </p>\r\n              <button\r\n                type=\"button\"\r\n                class=\"rounded-md border border-[var(--line-strong)] bg-[var(--surface)] px-3 py-1.5 text-sm font-medium text-[var(--ink-soft)] hover:border-[var(--accent)] hover:text-[var(--accent-ink)]\"\r\n                (click)=\"popupHost.popupOpen.set(!popupHost.popupOpen())\"\r\n              >\r\n                {{ popupHost.popupOpen() ? 'Close' : 'Open' }} popup\r\n              </button>\r\n              <app-popup-only #popupHost />\r\n            </div>\r\n          }\r\n          @case ('sidebar') {\r\n            <div class=\"space-y-3\">\r\n              <p class=\"text-sm text-[var(--ink-soft)]\">\r\n                <code>copilot-sidebar</code> is docked to the right at 480px.\r\n                Compact viewports render it as a modal even when\r\n                <code>mode</code> is <code>\"docked\"</code>, and only one open\r\n                docked sidebar can own the page margin at a time.\r\n              </p>\r\n              <button\r\n                type=\"button\"\r\n                class=\"rounded-md border border-[var(--line-strong)] bg-[var(--surface)] px-3 py-1.5 text-sm font-medium text-[var(--ink-soft)] hover:border-[var(--accent)] hover:text-[var(--accent-ink)]\"\r\n                (click)=\"sidebarHost.sidebarOpen.set(!sidebarHost.sidebarOpen())\"\r\n              >\r\n                {{ sidebarHost.sidebarOpen() ? 'Close' : 'Open' }} sidebar\r\n              </button>\r\n              <app-sidebar-only #sidebarHost />\r\n            </div>\r\n          }\r\n        }\r\n      </div>\r\n    </div>\r\n  `,\r\n})\r\nexport class ChatUiDemoComponent {\r\n  protected readonly surface = signal<Surface>('inline');\r\n  protected readonly tabs: ReadonlyArray<{ id: Surface; label: string }> = [\r\n    { id: 'inline', label: 'Inline chat' },\r\n    { id: 'custom-message', label: 'Custom assistant message' },\r\n    { id: 'popup', label: 'Popup' },\r\n    { id: 'sidebar', label: 'Sidebar' },\r\n  ];\r\n}\r\n",
  "src/app/features/chat-ui/custom-assistant-message.component.ts": "/**\r\n * \"Replace an assistant message\", verbatim.\r\n * https://docs.copilotkit.ai/angular/llamaindex/guides/chat-ui\r\n */\r\nimport { ChangeDetectionStrategy, Component, input } from '@angular/core';\r\n\r\ntype AssistantMessage = {\r\n  id: string;\r\n  role: 'assistant';\r\n  content?: string;\r\n};\r\n\r\n@Component({\r\n  selector: 'app-custom-assistant-message',\r\n  changeDetection: ChangeDetectionStrategy.OnPush,\r\n  template: `\r\n    <article class=\"answer\">\r\n      <span class=\"answer__label\">Assistant</span>\r\n      <p>{{ message().content }}</p>\r\n    </article>\r\n  `,\r\n})\r\nexport class CustomAssistantMessageComponent {\r\n  readonly message = input.required<AssistantMessage>();\r\n}\r\n",
  "src/app/features/chat-ui/custom-message-chat.component.ts": "/**\r\n * The second `SupportChatComponent` from \"Replace an assistant message\",\r\n * verbatim except for the class name and selector — the guide gives two\r\n * different components the same name and selector, and both are mounted here.\r\n * https://docs.copilotkit.ai/angular/llamaindex/guides/chat-ui\r\n */\r\nimport { Component } from '@angular/core';\r\nimport { CopilotChat } from '@copilotkit/angular';\r\n\r\nimport { CustomAssistantMessageComponent } from './custom-assistant-message.component';\r\n\r\n@Component({\r\n  selector: 'app-custom-message-chat',\r\n  imports: [CopilotChat],\r\n  template: `\r\n    <copilot-chat\r\n      [assistantMessageComponent]=\"assistantMessageComponent\"\r\n      assistantMessageClass=\"support-answer\"\r\n    />\r\n  `,\r\n})\r\nexport class CustomMessageChatComponent {\r\n  protected readonly assistantMessageComponent =\r\n    CustomAssistantMessageComponent;\r\n}\r\n",
  "src/app/features/chat-ui/popup-only.component.ts": "/**\r\n * The popup half of the guide's \"Use a popup or sidebar\" sample, on its own\r\n * host. Bindings are the guide's, unchanged.\r\n *\r\n * The guide declares `copilot-popup` and `copilot-sidebar` in one component.\r\n * Both render a launcher at the same fixed coordinates\r\n * (`right: max(1.5rem, …); bottom: max(1.5rem, …)`), so mounting them together\r\n * stacks two launchers on one spot and the sidebar — rendered second — takes\r\n * every click. Splitting them is what makes each surface separately testable;\r\n * the combined component is kept verbatim in popup-sidebar.component.ts and\r\n * shown as the source on the route page.\r\n *\r\n * https://docs.copilotkit.ai/angular/llamaindex/guides/chat-ui\r\n */\r\nimport { Component, signal } from '@angular/core';\r\nimport { CopilotPopup } from '@copilotkit/angular';\r\n\r\n@Component({\r\n  selector: 'app-popup-only',\r\n  imports: [CopilotPopup],\r\n  template: `\r\n    <copilot-popup\r\n      [(open)]=\"popupOpen\"\r\n      title=\"Support assistant\"\r\n      [clickOutsideToClose]=\"true\"\r\n    />\r\n  `,\r\n})\r\nexport class PopupOnlyComponent {\r\n  readonly popupOpen = signal(false);\r\n}\r\n",
  "src/app/features/chat-ui/popup-sidebar.component.ts": "/**\r\n * \"Use a popup or sidebar\", verbatim except for the class name and selector\r\n * (the guide mounts it as `AppComponent` / `app-root`).\r\n * https://docs.copilotkit.ai/angular/llamaindex/guides/chat-ui\r\n */\r\nimport { Component, signal } from '@angular/core';\r\nimport { CopilotPopup, CopilotSidebar } from '@copilotkit/angular';\r\n\r\n@Component({\r\n  selector: 'app-popup-sidebar',\r\n  imports: [CopilotPopup, CopilotSidebar],\r\n  template: `\r\n    <copilot-popup\r\n      [(open)]=\"popupOpen\"\r\n      title=\"Support assistant\"\r\n      [clickOutsideToClose]=\"true\"\r\n    />\r\n\r\n    <copilot-sidebar\r\n      [(open)]=\"sidebarOpen\"\r\n      mode=\"docked\"\r\n      position=\"right\"\r\n      title=\"Workspace assistant\"\r\n      [width]=\"480\"\r\n    />\r\n  `,\r\n})\r\nexport class PopupSidebarComponent {\r\n  readonly popupOpen = signal(false);\r\n  readonly sidebarOpen = signal(false);\r\n}\r\n",
  "src/app/features/chat-ui/sidebar-only.component.ts": "/**\r\n * The sidebar half of the guide's \"Use a popup or sidebar\" sample, on its own\r\n * host. Bindings are the guide's, unchanged.\r\n *\r\n * See popup-only.component.ts for why the guide's combined component is split\r\n * for the demo: both surfaces render a launcher at the same fixed coordinates.\r\n *\r\n * https://docs.copilotkit.ai/angular/llamaindex/guides/chat-ui\r\n */\r\nimport { Component, signal } from '@angular/core';\r\nimport { CopilotSidebar } from '@copilotkit/angular';\r\n\r\n@Component({\r\n  selector: 'app-sidebar-only',\r\n  imports: [CopilotSidebar],\r\n  template: `\r\n    <copilot-sidebar\r\n      [(open)]=\"sidebarOpen\"\r\n      mode=\"docked\"\r\n      position=\"right\"\r\n      title=\"Workspace assistant\"\r\n      [width]=\"480\"\r\n    />\r\n  `,\r\n})\r\nexport class SidebarOnlyComponent {\r\n  readonly sidebarOpen = signal(false);\r\n}\r\n",
  "src/app/features/chat-ui/support-chat.component.ts": "/**\r\n * \"Add an inline chat\", verbatim.\r\n * https://docs.copilotkit.ai/angular/llamaindex/guides/chat-ui\r\n *\r\n * `agentId=\"support\"` resolves because the runtime registers a `support` agent\r\n * alongside `default` (see frontend/server.ts).\r\n */\r\nimport { ChangeDetectionStrategy, Component } from '@angular/core';\r\nimport { CopilotChat } from '@copilotkit/angular';\r\n\r\n@Component({\r\n  selector: 'app-support-chat',\r\n  imports: [CopilotChat],\r\n  changeDetection: ChangeDetectionStrategy.OnPush,\r\n  template: `\r\n    <section class=\"chat-shell\" aria-label=\"Support assistant\">\r\n      <copilot-chat agentId=\"support\" />\r\n    </section>\r\n  `,\r\n  styles: `\r\n    .chat-shell {\r\n      height: min(48rem, 80vh);\r\n      overflow: hidden;\r\n      border: 1px solid #dbe3eb;\r\n      border-radius: 1rem;\r\n    }\r\n  `,\r\n})\r\nexport class SupportChatComponent {}\r\n",
  "src/app/features/headless/headless-chat.component.ts": "/**\r\n * \"Build a headless chat\", verbatim. No CopilotKit chrome: the transcript and\r\n * composer are hand-written over `injectAgentStore`, and the run is driven\r\n * through `CopilotKitCore.runAgent`.\r\n * https://docs.copilotkit.ai/angular/llamaindex/guides/threads-memory-attachments-headless\r\n */\r\nimport { Component, inject, signal } from '@angular/core';\r\nimport { CopilotKit, injectAgentStore } from '@copilotkit/angular';\r\n\r\n@Component({\r\n  selector: 'app-headless-chat',\r\n  template: `\r\n    <div aria-live=\"polite\">\r\n      @for (message of store().messages(); track message.id) {\r\n        <article [attr.data-role]=\"message.role\">\r\n          {{ message.content }}\r\n        </article>\r\n      }\r\n      @if (store().isRunning()) {\r\n        <p>Agent is working…</p>\r\n      }\r\n    </div>\r\n\r\n    <textarea\r\n      aria-label=\"Message\"\r\n      [value]=\"draft()\"\r\n      (input)=\"updateDraft($event)\"\r\n    ></textarea>\r\n    <button\r\n      type=\"button\"\r\n      [disabled]=\"store().isRunning() || !draft().trim()\"\r\n      (click)=\"send()\"\r\n    >\r\n      Send\r\n    </button>\r\n  `,\r\n})\r\nexport class HeadlessChatComponent {\r\n  private readonly copilotKit = inject(CopilotKit);\r\n  readonly store = injectAgentStore('default');\r\n  readonly draft = signal('');\r\n\r\n  protected updateDraft(event: Event): void {\r\n    this.draft.set((event.target as HTMLTextAreaElement).value);\r\n  }\r\n\r\n  protected async send(): Promise<void> {\r\n    const content = this.draft().trim();\r\n    if (!content || this.store().isRunning()) return;\r\n\r\n    const agent = this.store().agent;\r\n    agent.addMessage({\r\n      id: crypto.randomUUID(),\r\n      role: 'user',\r\n      content,\r\n    });\r\n    this.draft.set('');\r\n    await this.copilotKit.core.runAgent({ agent });\r\n  }\r\n}\r\n",
  "src/app/features/hitl/approval-card.component.ts": "/**\r\n * \"Register a decision tool\" renderer, verbatim.\r\n * https://docs.copilotkit.ai/angular/llamaindex/guides/human-in-the-loop\r\n */\r\nimport { Component, input } from '@angular/core';\r\nimport {\r\n  type HumanInTheLoopToolCall,\r\n  type HumanInTheLoopToolRenderer,\r\n} from '@copilotkit/angular';\r\n\r\ntype ApprovalArgs = {\r\n  action: string;\r\n  reason: string;\r\n};\r\n\r\n@Component({\r\n  selector: 'app-approval-card',\r\n  template: `\r\n    @let call = toolCall();\r\n    <article>\r\n      <h3>Approve {{ call.args.action ?? \"this action\" }}?</h3>\r\n      <p>{{ call.args.reason }}</p>\r\n\r\n      @if (call.status !== \"complete\") {\r\n        <button type=\"button\" (click)=\"call.respond({ approved: true })\">\r\n          Approve\r\n        </button>\r\n        <button type=\"button\" (click)=\"call.respond({ approved: false })\">\r\n          Reject\r\n        </button>\r\n      }\r\n    </article>\r\n  `,\r\n})\r\nexport class ApprovalCardComponent\r\n  implements HumanInTheLoopToolRenderer<ApprovalArgs>\r\n{\r\n  readonly toolCall = input.required<HumanInTheLoopToolCall<ApprovalArgs>>();\r\n}\r\n",
  "src/app/features/hitl/approval-tools.service.ts": "/**\r\n * \"Register the tool from the component or service that owns the decision UI\",\r\n * verbatim. There is no handler — CopilotKit supplies one that waits for\r\n * `respond`, returns the decision to the agent, and continues the run.\r\n * https://docs.copilotkit.ai/angular/llamaindex/guides/human-in-the-loop\r\n */\r\nimport { Injectable } from '@angular/core';\r\nimport { registerHumanInTheLoop } from '@copilotkit/angular';\r\nimport { z } from 'zod';\r\n\r\nimport { ApprovalCardComponent } from './approval-card.component';\r\n\r\n@Injectable()\r\nexport class ApprovalToolsService {\r\n  constructor() {\r\n    registerHumanInTheLoop({\r\n      name: 'requestApproval',\r\n      description: 'Ask the user before a consequential action',\r\n      parameters: z.object({\r\n        action: z.string(),\r\n        reason: z.string(),\r\n      }),\r\n      component: ApprovalCardComponent,\r\n    });\r\n  }\r\n}\r\n",
  "src/app/features/hitl/hitl-chat.component.ts": "/**\r\n * Puts the guide's two human-in-the-loop paths side by side: the decision tool\r\n * (registered by ApprovalToolsService, rendered inside the chat's tool-call\r\n * flow) and the headless interrupt controller (rendered outside the chat).\r\n * https://docs.copilotkit.ai/angular/llamaindex/guides/human-in-the-loop\r\n *\r\n * Injecting ApprovalToolsService is what constructs it, and construction is\r\n * what performs the `registerHumanInTheLoop` call.\r\n */\r\nimport { Component, inject } from '@angular/core';\r\nimport { CopilotChat } from '@copilotkit/angular';\r\n\r\nimport { ApprovalToolsService } from './approval-tools.service';\r\nimport { InterruptPanelComponent } from './interrupt-panel.component';\r\n\r\n@Component({\r\n  selector: 'app-hitl-chat',\r\n  imports: [CopilotChat, InterruptPanelComponent],\r\n  providers: [ApprovalToolsService],\r\n  template: `\r\n    <div style=\"display: flex; flex-direction: column; height: 100%\">\r\n      <app-interrupt-panel />\r\n      <div style=\"flex: 1; min-height: 0\">\r\n        <copilot-chat />\r\n      </div>\r\n    </div>\r\n  `,\r\n})\r\nexport class HitlChatComponent {\r\n  private readonly approvalTools = inject(ApprovalToolsService);\r\n}\r\n",
  "src/app/features/hitl/interrupt-panel.component.ts": "/**\r\n * \"Handle an interrupt\", verbatim. The controller is headless, so this panel\r\n * renders nothing until the backend emits an AG-UI interrupt.\r\n * https://docs.copilotkit.ai/angular/llamaindex/guides/human-in-the-loop\r\n */\r\nimport { Component } from '@angular/core';\r\nimport { injectInterrupt } from '@copilotkit/angular';\r\n\r\ntype ReviewRequest = {\r\n  title?: string;\r\n  choices?: Array<{ id: string; label: string }>;\r\n};\r\n\r\n@Component({\r\n  selector: 'app-interrupt-panel',\r\n  template: `\r\n    @if (controller.event(); as event) {\r\n      @let request = asReviewRequest(event.value);\r\n      <section aria-labelledby=\"review-title\">\r\n        <h2 id=\"review-title\">{{ request.title ?? \"Review required\" }}</h2>\r\n\r\n        @for (choice of request.choices ?? []; track choice.id) {\r\n          <button type=\"button\" (click)=\"resolve(choice.id)\">\r\n            {{ choice.label }}\r\n          </button>\r\n        }\r\n\r\n        <button type=\"button\" (click)=\"cancel()\">Cancel</button>\r\n      </section>\r\n    }\r\n\r\n    @if (controller.error()) {\r\n      <p role=\"alert\">The decision could not be submitted.</p>\r\n    }\r\n  `,\r\n})\r\nexport class InterruptPanelComponent {\r\n  protected readonly controller = injectInterrupt<ReviewRequest>({\r\n    agentId: 'default',\r\n  });\r\n\r\n  protected asReviewRequest(value: unknown): ReviewRequest {\r\n    return typeof value === 'object' && value !== null\r\n      ? (value as ReviewRequest)\r\n      : {};\r\n  }\r\n\r\n  protected resolve(choiceId: string): void {\r\n    this.controller.resolve({ choiceId }).catch(() => undefined);\r\n  }\r\n\r\n  protected cancel(): void {\r\n    this.controller.cancel().catch(() => undefined);\r\n  }\r\n}\r\n",
  "src/app/features/media/voice-chat.component.ts": "/**\r\n * \"Configure attachments\", verbatim: the guide's `MULTIMODAL_ATTACHMENTS`\r\n * config bound to the chat exactly as its `media-chat.component.html` snippet\r\n * shows. The microphone control needs no option — it is always present.\r\n * https://docs.copilotkit.ai/angular/llamaindex/guides/voice-multimodal\r\n */\r\nimport { Component } from '@angular/core';\r\nimport { CopilotChat, type AttachmentsConfig } from '@copilotkit/angular';\r\n\r\nconst MULTIMODAL_ATTACHMENTS: AttachmentsConfig = {\r\n  enabled: true,\r\n  accept: 'image/*,application/pdf',\r\n  maxSize: 10 * 1024 * 1024,\r\n};\r\n\r\n@Component({\r\n  selector: 'app-voice-chat',\r\n  imports: [CopilotChat],\r\n  template: `\r\n    <div style=\"height: 100%\">\r\n      <copilot-chat [attachments]=\"multimodalAttachments\" />\r\n    </div>\r\n  `,\r\n})\r\nexport class VoiceChatComponent {\r\n  protected readonly multimodalAttachments = MULTIMODAL_ATTACHMENTS;\r\n}\r\n",
  "src/app/features/memory/memory-demo.component.ts": "/**\r\n * Harness wrapper mounting the guide's memory list beside a chat, so the\r\n * `isAvailable()` gate can be observed against a live runtime.\r\n */\r\nimport { Component } from '@angular/core';\r\nimport { CopilotChat } from '@copilotkit/angular';\r\n\r\nimport { MemoryListComponent } from './memory-list.component';\r\n\r\n@Component({\r\n  selector: 'app-memory-demo',\r\n  imports: [CopilotChat, MemoryListComponent],\r\n  template: `\r\n    <div class=\"flex h-full gap-4 p-4\">\r\n      <section\r\n        class=\"w-80 shrink-0 overflow-y-auto rounded-lg border border-slate-200 bg-white p-4\"\r\n      >\r\n        <h2 class=\"mb-2 text-sm font-semibold text-slate-900\">\r\n          injectMemories\r\n        </h2>\r\n        <app-memory-list />\r\n      </section>\r\n      <div class=\"min-w-0 flex-1\">\r\n        <copilot-chat />\r\n      </div>\r\n    </div>\r\n  `,\r\n})\r\nexport class MemoryDemoComponent {}\r\n",
  "src/app/features/memory/memory-list.component.ts": "/**\r\n * \"Read and manage memory\", verbatim. The `isAvailable()` gate is the point of\r\n * the sample: a runtime may not provide the memory routes at all.\r\n * https://docs.copilotkit.ai/angular/llamaindex/guides/threads-memory-attachments-headless\r\n */\r\nimport { Component } from '@angular/core';\r\nimport { injectMemories } from '@copilotkit/angular';\r\n\r\n@Component({\r\n  selector: 'app-memory-list',\r\n  template: `\r\n    @if (!memory.isAvailable()) {\r\n      <p>Memory is not available for this runtime.</p>\r\n    } @else {\r\n      @for (item of memory.memories(); track item.id) {\r\n        <article>\r\n          <p>{{ item.content }}</p>\r\n          <button type=\"button\" (click)=\"remove(item.id)\">Forget</button>\r\n        </article>\r\n      }\r\n    }\r\n  `,\r\n})\r\nexport class MemoryListComponent {\r\n  readonly memory = injectMemories();\r\n\r\n  protected remove(id: string): void {\r\n    this.memory.removeMemory(id).catch(() => undefined);\r\n  }\r\n\r\n  protected addPreference(): void {\r\n    this.memory\r\n      .addMemory({\r\n        kind: 'operational',\r\n        content: 'Prefer concise status updates.',\r\n      })\r\n      .catch(() => undefined);\r\n  }\r\n}\r\n",
  "src/app/features/quickstart/quickstart-chat.ts": "/**\r\n * Quickstart step \"Add the chat UI\", verbatim.\r\n * https://docs.copilotkit.ai/angular/llamaindex/quickstart\r\n *\r\n * Only the selector and class name differ from the doc (which mounts this as\r\n * the app root); the template and imports are unchanged.\r\n */\r\nimport { Component } from '@angular/core';\r\nimport { CopilotChat } from '@copilotkit/angular';\r\n\r\n@Component({\r\n  selector: 'app-quickstart-chat',\r\n  imports: [CopilotChat],\r\n  template: `\r\n    <div style=\"height: 100vh\">\r\n      <copilot-chat />\r\n    </div>\r\n  `,\r\n})\r\nexport class QuickstartChat {}\r\n",
  "src/app/features/shared-state/account-context.component.ts": "/**\r\n * \"Send read-only application context\", verbatim. The accessor form keeps the\r\n * signal reads reactive, so changing the timezone re-registers the context.\r\n * https://docs.copilotkit.ai/angular/llamaindex/guides/shared-state\r\n */\r\nimport { Component, signal } from '@angular/core';\r\nimport { connectAgentContext } from '@copilotkit/angular';\r\n\r\n@Component({\r\n  selector: 'app-account-context',\r\n  template: `\r\n    <br>\r\n    <button type=\"button\" (click)=\"timezone.set('Europe/London')\">\r\n      Use London time\r\n    </button>\r\n  `,\r\n})\r\nexport class AccountContextComponent {\r\n  readonly userName = signal('Ada');\r\n  readonly timezone = signal('America/Los_Angeles');\r\n\r\n  constructor() {\r\n    connectAgentContext(() => ({\r\n      description: 'Current account and timezone',\r\n      value: JSON.stringify({\r\n        userName: this.userName(),\r\n        timezone: this.timezone(),\r\n      }),\r\n    }));\r\n  }\r\n}\r\n",
  "src/app/features/shared-state/selection-context.component.ts": "/**\r\n * \"Bind context in a template\", verbatim. The directive registers on first\r\n * render, so it must not be rendered before the context is complete.\r\n * https://docs.copilotkit.ai/angular/llamaindex/guides/shared-state\r\n */\r\nimport { Component, computed, signal } from '@angular/core';\r\nimport { CopilotKitAgentContext } from '@copilotkit/angular';\r\n\r\n@Component({\r\n  selector: 'app-selection-context',\r\n  imports: [CopilotKitAgentContext],\r\n  template: ` <div [copilotkitAgentContext]=\"selectionContext()\"></div> `,\r\n})\r\nexport class SelectionContextComponent {\r\n  readonly selectedId = signal('record-42');\r\n  readonly selectionContext = computed(() => ({\r\n    description: 'The record selected in the application',\r\n    value: this.selectedId(),\r\n  }));\r\n}\r\n",
  "src/app/features/shared-state/shared-state-chat.component.ts": "/**\r\n * Mounts the guide's three surfaces against one chat: the read/write state\r\n * panel, the accessor-based context, and the directive-based context.\r\n * https://docs.copilotkit.ai/angular/llamaindex/guides/shared-state\r\n */\r\nimport { Component } from '@angular/core';\r\nimport { CopilotChat } from '@copilotkit/angular';\r\n\r\nimport { AccountContextComponent } from './account-context.component';\r\nimport { SelectionContextComponent } from './selection-context.component';\r\nimport { WorkspaceComponent } from './workspace.component';\r\n\r\n@Component({\r\n  selector: 'app-shared-state-chat',\r\n  imports: [\r\n    CopilotChat,\r\n    WorkspaceComponent,\r\n    AccountContextComponent,\r\n    SelectionContextComponent,\r\n  ],\r\n  template: `\r\n    <div style=\"display: flex; height: 100%; gap: 1rem\">\r\n      <div style=\"width: 20rem; overflow-y: auto; padding: 1rem\">\r\n        <app-workspace />\r\n        <app-account-context />\r\n        <app-selection-context />\r\n      </div>\r\n      <div style=\"flex: 1; min-width: 0\">\r\n        <copilot-chat />\r\n      </div>\r\n    </div>\r\n  `,\r\n})\r\nexport class SharedStateChatComponent {}\r\n",
  "src/app/features/shared-state/workspace.component.ts": "/**\r\n * \"Read agent state\", verbatim. Reads through `store().state()` so Angular\r\n * tracks changes; writes through the plain AG-UI agent at `store().agent`.\r\n * https://docs.copilotkit.ai/angular/llamaindex/guides/shared-state\r\n */\r\nimport { Component, computed } from '@angular/core';\r\nimport { injectAgentStore } from '@copilotkit/angular';\r\n\r\ntype WorkspaceState = {\r\n  notes: string[];\r\n  priority: 'low' | 'normal' | 'high';\r\n};\r\n\r\nconst EMPTY_STATE: WorkspaceState = {\r\n  notes: [],\r\n  priority: 'normal',\r\n};\r\n\r\n@Component({\r\n  selector: 'app-workspace',\r\n  template: `\r\n    <p>Priority: {{ state().priority }}</p>\r\n    <ul>\r\n      @for (note of state().notes; track note) {\r\n        <li>{{ note }}</li>\r\n      }\r\n    </ul>\r\n    <button type=\"button\" (click)=\"setPriority('high')\">\r\n      Mark high priority\r\n    </button>\r\n    <br>\r\n     <button type=\"button\" (click)=\"setPriority('low')\">\r\n      Mark low priority\r\n    </button>\r\n  `,\r\n})\r\nexport class WorkspaceComponent {\r\n  readonly store = injectAgentStore('default');\r\n  readonly state = computed(\r\n    () => (this.store().state() as WorkspaceState | undefined) ?? EMPTY_STATE,\r\n  );\r\n\r\n  protected setPriority(priority: WorkspaceState['priority']): void {\r\n    const agent = this.store().agent;\r\n    const current = (agent.state as WorkspaceState | undefined) ?? EMPTY_STATE;\r\n    agent.setState({ ...current, priority });\r\n  }\r\n}\r\n",
  "src/app/features/subagents/agent-state-cards.ts": "/**\r\n * DOC GAP FILL — `SubAgentActivityCard` (the in-chat renderer) and `DelegationLogComponent` (the live log).\r\n *\r\n * The Sub-Agents page prints only a fragment of the Angular Showcase's\r\n * agent-state-feature.component.ts, which calls helpers it never shows. This\r\n * file is that helper, copied verbatim (below this comment) from the source\r\n * the page names:\r\n * https://github.com/CopilotKit/CopilotKit/blob/main/showcase/angular/src/app/features/agent-state/agent-state-cards.ts\r\n *\r\n * Doc page: https://docs.copilotkit.ai/angular/llamaindex/multi-agent/subagents\r\n */\r\nimport {\r\n  ChangeDetectionStrategy,\r\n  Component,\r\n  computed,\r\n  input,\r\n} from \"@angular/core\";\r\nimport type { AngularToolCall } from \"@copilotkit/angular\";\r\n\r\nimport type { AgentStep, Delegation, SubAgentName } from \"./agent-state-model\";\r\n\r\n@Component({\r\n  selector: \"showcase-agent-state-card\",\r\n  changeDetection: ChangeDetectionStrategy.OnPush,\r\n  host: { class: \"agent-state-card-host\" },\r\n  template: `\r\n    <article class=\"agent-state-card\" data-testid=\"agent-state-card\">\r\n      <header>\r\n        <span class=\"status-dot\" [class.running]=\"isRunning()\"></span>\r\n        <strong>{{ headline() }}</strong>\r\n      </header>\r\n      @if (steps().length > 0) {\r\n        <ol>\r\n          @for (step of steps(); track step.id; let index = $index) {\r\n            <li data-testid=\"agent-step\" [attr.data-status]=\"step.status\">\r\n              <span class=\"step-marker\" aria-hidden=\"true\">\r\n                {{ step.status === \"completed\" ? \"✓\" : index + 1 }}\r\n              </span>\r\n              <span [class.completed]=\"step.status === 'completed'\">\r\n                {{ step.title }}\r\n              </span>\r\n            </li>\r\n          }\r\n        </ol>\r\n      }\r\n    </article>\r\n  `,\r\n  styles: `\r\n    :host {\r\n      display: block;\r\n      margin: 0.75rem 1rem;\r\n    }\r\n    .agent-state-card {\r\n      padding: 1rem;\r\n      border: 1px solid #d8e0ea;\r\n      border-radius: 1rem;\r\n      background: #fff;\r\n      box-shadow: 0 8px 24px rgb(30 49 73 / 8%);\r\n    }\r\n    header,\r\n    li {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 0.65rem;\r\n    }\r\n    header {\r\n      color: #152238;\r\n      font-size: 0.9rem;\r\n    }\r\n    .status-dot {\r\n      width: 0.65rem;\r\n      height: 0.65rem;\r\n      border-radius: 50%;\r\n      background: #22a06b;\r\n    }\r\n    .status-dot.running {\r\n      background: #4f46e5;\r\n      box-shadow: 0 0 0 0.25rem #e0e7ff;\r\n    }\r\n    ol {\r\n      display: grid;\r\n      gap: 0.55rem;\r\n      margin: 0.85rem 0 0;\r\n      padding: 0;\r\n      list-style: none;\r\n    }\r\n    li {\r\n      color: #334155;\r\n      font-size: 0.82rem;\r\n    }\r\n    .step-marker {\r\n      display: inline-grid;\r\n      width: 1.35rem;\r\n      height: 1.35rem;\r\n      flex: 0 0 auto;\r\n      place-items: center;\r\n      border: 1px solid #cbd5e1;\r\n      border-radius: 50%;\r\n      font-size: 0.68rem;\r\n      font-weight: 700;\r\n    }\r\n    .completed {\r\n      color: #718096;\r\n      text-decoration: line-through;\r\n    }\r\n  `,\r\n})\r\nexport class AgentStateCardComponent {\r\n  readonly steps = input.required<AgentStep[]>();\r\n  readonly isRunning = input(false);\r\n  protected readonly headline = computed(() => {\r\n    const steps = this.steps();\r\n    const done = steps.filter((step) => step.status === \"completed\").length;\r\n    if (steps.length === 0) return \"Planning…\";\r\n    if (!this.isRunning() || done === steps.length) {\r\n      return `All ${done} steps complete`;\r\n    }\r\n    return `Step ${Math.min(done + 1, steps.length)} of ${steps.length}`;\r\n  });\r\n}\r\n\r\nconst SUB_AGENT_META: Readonly<\r\n  Record<\r\n    SubAgentName,\r\n    {\r\n      label: string;\r\n      testId: string;\r\n      delegationTestId: string;\r\n      action: string;\r\n    }\r\n  >\r\n> = {\r\n  research_agent: {\r\n    label: \"Researcher\",\r\n    testId: \"subagent-card-researcher\",\r\n    delegationTestId: \"subagent-delegation-researcher\",\r\n    action: \"gathering facts\",\r\n  },\r\n  writing_agent: {\r\n    label: \"Writer\",\r\n    testId: \"subagent-card-writer\",\r\n    delegationTestId: \"subagent-delegation-writer\",\r\n    action: \"drafting prose\",\r\n  },\r\n  critique_agent: {\r\n    label: \"Critic\",\r\n    testId: \"subagent-card-critic\",\r\n    delegationTestId: \"subagent-delegation-critic\",\r\n    action: \"reviewing the draft\",\r\n  },\r\n};\r\n\r\n@Component({\r\n  selector: \"showcase-subagent-activity-card\",\r\n  changeDetection: ChangeDetectionStrategy.OnPush,\r\n  template: `\r\n    <article\r\n      class=\"subagent-card\"\r\n      [attr.data-testid]=\"meta().testId\"\r\n      [attr.data-sub-agent]=\"subAgent()\"\r\n      [attr.data-status]=\"toolCall().status\"\r\n    >\r\n      <header>\r\n        <strong>{{ meta().label }}</strong>\r\n        <span>{{ complete() ? \"Complete\" : \"Working\" }}</span>\r\n      </header>\r\n      <p><b>Task:</b> {{ toolCall().args.task || \"Receiving task…\" }}</p>\r\n      @if (complete()) {\r\n        <p data-testid=\"subagent-result\"><b>Result:</b> {{ toolCall().result }}</p>\r\n      } @else {\r\n        <p>{{ meta().label }} is {{ meta().action }}…</p>\r\n      }\r\n    </article>\r\n  `,\r\n  styles: `\r\n    :host {\r\n      display: block;\r\n      margin: 0.75rem 0;\r\n    }\r\n    .subagent-card {\r\n      overflow: hidden;\r\n      border: 1px solid #c7d2fe;\r\n      border-radius: 1rem;\r\n      color: #18253a;\r\n      background: #f8faff;\r\n      box-shadow: 0 6px 20px rgb(49 46 129 / 8%);\r\n    }\r\n    header {\r\n      display: flex;\r\n      justify-content: space-between;\r\n      gap: 1rem;\r\n      padding: 0.7rem 0.9rem;\r\n      border-bottom: 1px solid #dbe3f0;\r\n      background: #eef2ff;\r\n    }\r\n    header span {\r\n      color: #475569;\r\n      font-size: 0.7rem;\r\n      font-weight: 700;\r\n      letter-spacing: 0.08em;\r\n      text-transform: uppercase;\r\n    }\r\n    p {\r\n      margin: 0;\r\n      padding: 0.7rem 0.9rem;\r\n      white-space: pre-wrap;\r\n      font-size: 0.8rem;\r\n      line-height: 1.5;\r\n    }\r\n    p + p {\r\n      padding-top: 0;\r\n    }\r\n  `,\r\n})\r\nexport class SubAgentActivityCard {\r\n  readonly toolCall = input.required<AngularToolCall<{ task: string }>>();\r\n  protected readonly subAgent = computed(() => {\r\n    const name = this.toolCall().name;\r\n    return isSubAgentName(name) ? name : \"research_agent\";\r\n  });\r\n  protected readonly meta = computed(() => SUB_AGENT_META[this.subAgent()]);\r\n  protected readonly complete = computed(\r\n    () => this.toolCall().status === \"complete\",\r\n  );\r\n}\r\n\r\nfunction isSubAgentName(value: unknown): value is SubAgentName {\r\n  return (\r\n    value === \"research_agent\" ||\r\n    value === \"writing_agent\" ||\r\n    value === \"critique_agent\"\r\n  );\r\n}\r\n\r\n@Component({\r\n  selector: \"showcase-delegation-log\",\r\n  changeDetection: ChangeDetectionStrategy.OnPush,\r\n  template: `\r\n    <section class=\"delegation-log\" data-testid=\"delegation-log\">\r\n      <header>\r\n        <div>\r\n          <p>Supervisor</p>\r\n          <h1>Sub-agent delegations</h1>\r\n        </div>\r\n        <span data-testid=\"delegation-count\">{{ delegations().length }} calls</span>\r\n      </header>\r\n      <div class=\"role-row\" aria-label=\"Available sub-agents\">\r\n        @for (role of roles; track role.subAgent) {\r\n          <span [attr.data-fired]=\"called(role.subAgent)\">{{ role.label }}</span>\r\n        }\r\n      </div>\r\n      @if (delegations().length === 0) {\r\n        <p class=\"empty\">\r\n          Ask the supervisor to research, write, and critique a task.\r\n        </p>\r\n      } @else {\r\n        <ol>\r\n          @for (\r\n            delegation of delegations();\r\n            track delegation.id;\r\n            let index = $index\r\n          ) {\r\n            <li\r\n              [attr.data-testid]=\"testIdFor(delegation.subAgent)\"\r\n              [attr.data-status]=\"delegation.status\"\r\n            >\r\n              <strong>{{ index + 1 }}. {{ labelFor(delegation.subAgent) }}</strong>\r\n              <span>{{ delegation.status }}</span>\r\n              <p>{{ delegation.task }}</p>\r\n              <blockquote>{{ delegation.result }}</blockquote>\r\n            </li>\r\n          }\r\n        </ol>\r\n      }\r\n    </section>\r\n  `,\r\n  styles: `\r\n    :host {\r\n      display: block;\r\n      min-width: 0;\r\n    }\r\n    .delegation-log {\r\n      overflow: hidden;\r\n      border: 1px solid #d8e0ea;\r\n      border-radius: 1rem;\r\n      background: #fff;\r\n      box-shadow: 0 12px 34px rgb(30 49 73 / 8%);\r\n    }\r\n    header {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: space-between;\r\n      gap: 1rem;\r\n      padding: 1rem;\r\n      border-bottom: 1px solid #e2e8f0;\r\n    }\r\n    header p,\r\n    header h1 {\r\n      margin: 0;\r\n    }\r\n    header p {\r\n      color: #6366f1;\r\n      font-size: 0.7rem;\r\n      font-weight: 750;\r\n      letter-spacing: 0.12em;\r\n      text-transform: uppercase;\r\n    }\r\n    header h1 {\r\n      margin-top: 0.2rem;\r\n      color: #152238;\r\n      font-size: 1.1rem;\r\n    }\r\n    header span {\r\n      color: #64748b;\r\n      font-size: 0.75rem;\r\n    }\r\n    .role-row {\r\n      display: flex;\r\n      flex-wrap: wrap;\r\n      gap: 0.5rem;\r\n      padding: 0.75rem 1rem;\r\n      border-bottom: 1px solid #e2e8f0;\r\n    }\r\n    .role-row span {\r\n      padding: 0.3rem 0.55rem;\r\n      border: 1px solid #cbd5e1;\r\n      border-radius: 999px;\r\n      color: #64748b;\r\n      font-size: 0.72rem;\r\n    }\r\n    .role-row span[data-fired=\"true\"] {\r\n      border-color: #818cf8;\r\n      color: #3730a3;\r\n      background: #eef2ff;\r\n    }\r\n    .empty {\r\n      margin: 0;\r\n      padding: 1rem;\r\n      color: #64748b;\r\n      font-size: 0.85rem;\r\n    }\r\n    ol {\r\n      display: grid;\r\n      gap: 0.75rem;\r\n      margin: 0;\r\n      padding: 1rem;\r\n      list-style: none;\r\n    }\r\n    li {\r\n      padding: 0.8rem;\r\n      border: 1px solid #e2e8f0;\r\n      border-radius: 0.75rem;\r\n      background: #f8fafc;\r\n    }\r\n    li > span {\r\n      float: right;\r\n      color: #15803d;\r\n      font-size: 0.7rem;\r\n      text-transform: uppercase;\r\n    }\r\n    li p,\r\n    blockquote {\r\n      margin: 0.5rem 0 0;\r\n      color: #475569;\r\n      font-size: 0.78rem;\r\n      line-height: 1.45;\r\n    }\r\n    blockquote {\r\n      padding: 0.65rem;\r\n      border-radius: 0.5rem;\r\n      background: #fff;\r\n    }\r\n  `,\r\n})\r\nexport class DelegationLogComponent {\r\n  readonly delegations = input.required<Delegation[]>();\r\n  protected readonly roles = [\r\n    { subAgent: \"research_agent\" as const, label: \"Researcher\" },\r\n    { subAgent: \"writing_agent\" as const, label: \"Writer\" },\r\n    { subAgent: \"critique_agent\" as const, label: \"Critic\" },\r\n  ];\r\n\r\n  protected called(subAgent: SubAgentName): boolean {\r\n    return this.delegations().some(\r\n      (delegation) => delegation.subAgent === subAgent,\r\n    );\r\n  }\r\n\r\n  protected labelFor(subAgent: SubAgentName): string {\r\n    return SUB_AGENT_META[subAgent].label;\r\n  }\r\n\r\n  /** Resolve a delegation-log identity distinct from transcript tool cards. */\r\n  protected testIdFor(subAgent: SubAgentName): string {\r\n    return SUB_AGENT_META[subAgent].delegationTestId;\r\n  }\r\n}\r\n",
  "src/app/features/subagents/agent-state-model.ts": "/**\r\n * DOC GAP FILL — `readDelegations` and `SubAgentName`.\r\n *\r\n * The Sub-Agents page prints only a fragment of the Angular Showcase's\r\n * agent-state-feature.component.ts, which calls helpers it never shows. This\r\n * file is that helper, copied verbatim (below this comment) from the source\r\n * the page names:\r\n * https://github.com/CopilotKit/CopilotKit/blob/main/showcase/angular/src/app/features/agent-state/agent-state-model.ts\r\n *\r\n * Doc page: https://docs.copilotkit.ai/angular/llamaindex/multi-agent/subagents\r\n */\r\nexport type StepStatus = \"pending\" | \"in_progress\" | \"completed\";\r\n\r\nexport interface AgentStep {\r\n  id: string;\r\n  title: string;\r\n  status: StepStatus;\r\n}\r\n\r\nexport type SubAgentName =\r\n  | \"research_agent\"\r\n  | \"writing_agent\"\r\n  | \"critique_agent\";\r\n\r\nexport interface Delegation {\r\n  id: string;\r\n  subAgent: SubAgentName;\r\n  task: string;\r\n  status: \"completed\";\r\n  result: string;\r\n}\r\n\r\n/** Read the planner's streamed state without trusting backend payload shapes. */\r\nexport function readSteps(state: unknown): AgentStep[] {\r\n  const steps = readArraySlot(state, \"steps\");\r\n  return steps.flatMap((candidate) => {\r\n    if (!isRecord(candidate)) return [];\r\n    const { id, title, status } = candidate;\r\n    if (\r\n      typeof id !== \"string\" ||\r\n      typeof title !== \"string\" ||\r\n      !isStepStatus(status)\r\n    ) {\r\n      return [];\r\n    }\r\n    return [{ id, title, status }];\r\n  });\r\n}\r\n\r\n/** Read completed supervisor delegations from append-only agent state. */\r\nexport function readDelegations(state: unknown): Delegation[] {\r\n  const delegations = readArraySlot(state, \"delegations\");\r\n  return delegations.flatMap((candidate) => {\r\n    if (!isRecord(candidate)) return [];\r\n    const { id, sub_agent: subAgent, task, status, result } = candidate;\r\n    if (\r\n      typeof id !== \"string\" ||\r\n      !isSubAgentName(subAgent) ||\r\n      typeof task !== \"string\" ||\r\n      status !== \"completed\" ||\r\n      typeof result !== \"string\"\r\n    ) {\r\n      return [];\r\n    }\r\n    return [{ id, subAgent, task, status, result }];\r\n  });\r\n}\r\n\r\nfunction readArraySlot(state: unknown, slot: string): unknown[] {\r\n  if (!isRecord(state)) return [];\r\n  const value = state[slot];\r\n  return Array.isArray(value) ? value : [];\r\n}\r\n\r\nfunction isRecord(value: unknown): value is Record<string, unknown> {\r\n  return typeof value === \"object\" && value !== null;\r\n}\r\n\r\nfunction isStepStatus(value: unknown): value is StepStatus {\r\n  return (\r\n    value === \"pending\" || value === \"in_progress\" || value === \"completed\"\r\n  );\r\n}\r\n\r\nfunction isSubAgentName(value: unknown): value is SubAgentName {\r\n  return (\r\n    value === \"research_agent\" ||\r\n    value === \"writing_agent\" ||\r\n    value === \"critique_agent\"\r\n  );\r\n}\r\n",
  "src/app/features/subagents/subagent-renderer-config.ts": "/**\r\n * DOC GAP FILL — `subAgentRendererConfig`.\r\n *\r\n * The Sub-Agents page prints only a fragment of the Angular Showcase's\r\n * agent-state-feature.component.ts, which calls helpers it never shows. This\r\n * file is that helper, copied verbatim (below this comment) from the source\r\n * the page names:\r\n * https://github.com/CopilotKit/CopilotKit/blob/main/showcase/angular/src/app/features/agent-state/subagent-renderer-config.ts\r\n *\r\n * Doc page: https://docs.copilotkit.ai/angular/llamaindex/multi-agent/subagents\r\n */\r\nimport type { RenderToolCallConfig } from \"@copilotkit/angular\";\r\nimport { z } from \"zod\";\r\n\r\nimport { SubAgentActivityCard } from \"./agent-state-cards\";\r\nimport type { SubAgentName } from \"./agent-state-model\";\r\n\r\n/**\r\n * Build a route-lifetime subagent renderer that also matches runtimes whose\r\n * assistant messages do not carry an agent identifier.\r\n */\r\nexport function subAgentRendererConfig(\r\n  name: SubAgentName,\r\n): RenderToolCallConfig<{ task: string }> {\r\n  return {\r\n    name,\r\n    args: z.object({ task: z.string() }),\r\n    component: SubAgentActivityCard as unknown as RenderToolCallConfig<{\r\n      task: string;\r\n    }>[\"component\"],\r\n  };\r\n}\r\n",
  "src/app/features/subagents/subagents-chat.component.ts": "/**\r\n * \"Rendering a live delegation log\", from\r\n * https://docs.copilotkit.ai/angular/llamaindex/multi-agent/subagents\r\n *\r\n * The class body between the region markers is the page's TypeScript sample,\r\n * verbatim. That sample is a fragment of the Angular Showcase's\r\n * agent-state-feature.component.ts, so three things around it are not on the\r\n * page:\r\n *\r\n * - `readDelegations`, `SubAgentName`, `subAgentRendererConfig`, and the two\r\n *   components rendered here come from the showcase files the page names —\r\n *   see the DOC GAP FILL header on each file in this folder.\r\n * - `agentId` and `feature`. The showcase derives them from route data and an\r\n *   integration lookup that the page does not print. Here they are the literal\r\n *   values that showcase path resolves to for this page: the `subagents`\r\n *   agent (registered in frontend/server.ts) and the `subagents` feature.\r\n * - The template. The page shows none; this one mounts the delegation log\r\n *   beside a chat, which is what the showcase does for this feature.\r\n */\r\nimport { Component, computed } from '@angular/core';\r\nimport {\r\n  CopilotChat,\r\n  injectAgentStore,\r\n  registerRenderToolCall,\r\n} from '@copilotkit/angular';\r\n\r\nimport { DelegationLogComponent } from './agent-state-cards';\r\nimport type { SubAgentName } from './agent-state-model';\r\nimport { readDelegations } from './agent-state-model';\r\nimport { subAgentRendererConfig } from './subagent-renderer-config';\r\n\r\n@Component({\r\n  selector: 'app-subagents-chat',\r\n  imports: [CopilotChat, DelegationLogComponent],\r\n  template: `\r\n    <div class=\"subagents\">\r\n      <aside aria-label=\"Live supervisor delegation state\">\r\n        <showcase-delegation-log [delegations]=\"delegations()\" />\r\n      </aside>\r\n      <section class=\"chat-surface\" aria-label=\"CopilotKit assistant\">\r\n        <copilot-chat agentId=\"subagents\" />\r\n      </section>\r\n    </div>\r\n  `,\r\n  styles: `\r\n    .subagents {\r\n      display: grid;\r\n      grid-template-columns: minmax(18rem, 0.85fr) minmax(0, 1.35fr);\r\n      gap: 1rem;\r\n      height: 100%;\r\n      padding: 1rem;\r\n    }\r\n    .subagents aside {\r\n      min-width: 0;\r\n      overflow: auto;\r\n    }\r\n    .chat-surface {\r\n      min-width: 0;\r\n      overflow: hidden;\r\n      border: 1px solid #d8e0ea;\r\n      border-radius: 1rem;\r\n    }\r\n  `,\r\n})\r\nexport class SubagentsChatComponent {\r\n  // Not on the page — see the file header.\r\n  private readonly agentId = 'subagents';\r\n  protected readonly feature = 'subagents';\r\n\r\n  // @region[subagent-delegation-state] — verbatim from the doc page.\r\n  private readonly agentStore = injectAgentStore(this.agentId);\r\n  protected readonly delegations = computed(() =>\r\n    readDelegations(this.agentStore().state()),\r\n  );\r\n\r\n  constructor() {\r\n    if (this.feature === \"subagents\") {\r\n      this.registerSubAgent(\"research_agent\");\r\n      this.registerSubAgent(\"writing_agent\");\r\n      this.registerSubAgent(\"critique_agent\");\r\n    }\r\n  }\r\n\r\n  private registerSubAgent(name: SubAgentName): void {\r\n    registerRenderToolCall(subAgentRendererConfig(name));\r\n  }\r\n  // @endregion[subagent-delegation-state]\r\n}\r\n",
  "src/app/features/threads/conversations.component.ts": "/**\r\n * The drawer-plus-chat sample, verbatim. Both sit under one\r\n * `provideCopilotChatConfiguration`, which is what makes selection and\r\n * new-thread actions in the drawer update the chat.\r\n * https://docs.copilotkit.ai/angular/llamaindex/guides/threads-memory-attachments-headless\r\n */\r\nimport { Component } from '@angular/core';\r\nimport {\r\n  CopilotChat,\r\n  CopilotThreadsDrawer,\r\n  provideCopilotChatConfiguration,\r\n} from '@copilotkit/angular';\r\n\r\n@Component({\r\n  selector: 'app-conversations',\r\n  imports: [CopilotChat, CopilotThreadsDrawer],\r\n  providers: [provideCopilotChatConfiguration({ agentId: 'support' })],\r\n  template: `\r\n    <copilot-threads-drawer agentId=\"support\" [limit]=\"20\" />\r\n    <copilot-chat />\r\n  `,\r\n})\r\nexport class ConversationsComponent {}\r\n",
  "src/app/features/threads/thread-list.component.ts": "/**\r\n * \"For a custom thread list, use injectThreads\", verbatim.\r\n * https://docs.copilotkit.ai/angular/llamaindex/guides/threads-memory-attachments-headless\r\n */\r\nimport { Component } from '@angular/core';\r\nimport { injectThreads } from '@copilotkit/angular';\r\n\r\n@Component({\r\n  selector: 'app-thread-list',\r\n  template: `\r\n    <button type=\"button\" (click)=\"threads.startNewThread()\">\r\n      New conversation\r\n    </button>\r\n\r\n    @if (threads.isLoading()) {\r\n      <p>Loading conversations…</p>\r\n    } @else {\r\n      @for (thread of threads.threads(); track thread.id) {\r\n        <button type=\"button\" (click)=\"select(thread.id)\">\r\n          {{ thread.name ?? \"Untitled conversation\" }}\r\n        </button>\r\n      }\r\n    }\r\n\r\n    @if (threads.listError()) {\r\n      <button type=\"button\" (click)=\"threads.refetchThreads()\">Retry</button>\r\n    }\r\n  `,\r\n})\r\nexport class ThreadListComponent {\r\n  readonly threads = injectThreads({\r\n    agentId: 'support',\r\n    limit: 20,\r\n  });\r\n\r\n  protected select(threadId: string): void {\r\n    // Store this id and bind it to CopilotChat's threadId input.\r\n    console.log(threadId);\r\n  }\r\n}\r\n",
  "src/app/features/threads/threads-demo.component.ts": "/**\r\n * Harness wrapper mounting both thread surfaces from the guide: the hand-built\r\n * list on `injectThreads`, and the drop-in drawer beside a chat.\r\n */\r\nimport { Component } from '@angular/core';\r\n\r\nimport { ConversationsComponent } from './conversations.component';\r\nimport { ThreadListComponent } from './thread-list.component';\r\n\r\n@Component({\r\n  selector: 'app-threads-demo',\r\n  imports: [ThreadListComponent, ConversationsComponent],\r\n  template: `\r\n    <div class=\"flex h-full flex-col gap-4 p-4\">\r\n      <section class=\"rounded-lg border border-slate-200 bg-white p-4\">\r\n        <h2 class=\"mb-2 text-sm font-semibold text-slate-900\">\r\n          Headless list — injectThreads\r\n        </h2>\r\n        <app-thread-list />\r\n      </section>\r\n\r\n      <section\r\n        class=\"flex min-h-0 flex-1 flex-col rounded-lg border border-slate-200 bg-white p-4\"\r\n      >\r\n        <h2 class=\"mb-2 text-sm font-semibold text-slate-900\">\r\n          CopilotThreadsDrawer + chat\r\n        </h2>\r\n        <div class=\"flex min-h-0 flex-1 gap-4\">\r\n          <app-conversations />\r\n        </div>\r\n      </section>\r\n    </div>\r\n  `,\r\n})\r\nexport class ThreadsDemoComponent {}\r\n",
  "src/app/features/tools/incident-card.component.ts": "/**\r\n * \"Let the agent display one of your components\", verbatim.\r\n * https://docs.copilotkit.ai/angular/llamaindex/guides/frontend-tools-generative-ui\r\n *\r\n * Two deviations from the published snippet, both mechanical:\r\n * `standalone: true` is dropped — it is the default on Angular v20+ and\r\n * frontend/AGENTS.md forbids setting it — and the two imports are narrowed to\r\n * `type` imports, matching weather-card.component.ts.\r\n *\r\n * Unlike WeatherCardComponent this renderer never reads `call.result`: a\r\n * display-only component has no application code behind it, so the tool\r\n * completes with an empty result and the args are the whole payload.\r\n */\r\nimport { Component, input } from '@angular/core';\r\nimport { type AngularToolCall, type ToolRenderer } from '@copilotkit/angular';\r\n\r\ntype IncidentArgs = { id: string; severity: string };\r\n\r\n@Component({\r\n  selector: 'app-incident-card',\r\n  template: `\r\n    @let call = toolCall();\r\n    @if (call.status === \"in-progress\") {\r\n      <p>Loading incident…</p>\r\n    } @else {\r\n      <article>\r\n        <strong>{{ call.args.id }}</strong>\r\n        <span>{{ call.args.severity }}</span>\r\n      </article>\r\n    }\r\n  `,\r\n})\r\nexport class IncidentCardComponent implements ToolRenderer<IncidentArgs> {\r\n  readonly toolCall = input.required<AngularToolCall<IncidentArgs>>();\r\n}\r\n",
  "src/app/features/tools/tool-feature-model.ts": "/**\r\n * The guide's `change_background` frontend tool.\r\n * https://docs.copilotkit.ai/angular/llamaindex/guides/frontend-tools-generative-ui\r\n *\r\n * `createBackgroundTool` is the guide's function, unchanged. Everything above\r\n * it is not in the guide: the snippet is quoted from the live Showcase without\r\n * its `BackgroundToolArgs` type, its `resolveGradient` helper, or its imports,\r\n * so those are defined here to make it runnable.\r\n */\r\nimport { type WritableSignal } from '@angular/core';\r\nimport { type FrontendToolConfig } from '@copilotkit/angular';\r\nimport { z } from 'zod';\r\n\r\n/** Arguments the agent may send to `change_background`. */\r\nexport type BackgroundToolArgs = {\r\n  background?: string;\r\n  color?: string;\r\n};\r\n\r\n/** Named presets so the agent can ask for a look without writing CSS. */\r\nconst GRADIENT_PRESETS: Record<string, string> = {\r\n  blue: 'linear-gradient(180deg, #0c4a6e 0%, #38bdf8 100%)',\r\n  violet: 'linear-gradient(180deg, #4c1d95 0%, #c084fc 100%)',\r\n  sunset: 'linear-gradient(180deg, #f97316 0%, #db2777 55%, #7c3aed 100%)',\r\n  forest: 'linear-gradient(180deg, #14532d 0%, #4ade80 100%)',\r\n  slate: 'linear-gradient(180deg, #0f172a 0%, #475569 100%)',\r\n};\r\n\r\nexport const DEFAULT_BACKGROUND = GRADIENT_PRESETS['slate'];\r\n\r\n/**\r\n * Accept a preset name, a bare CSS color, or a full gradient and always return\r\n * something safe to drop into a `background` style binding.\r\n */\r\nexport function resolveGradient(value: string | undefined): string {\r\n  const raw = value?.trim();\r\n  if (!raw) {\r\n    return DEFAULT_BACKGROUND;\r\n  }\r\n\r\n  const preset = GRADIENT_PRESETS[raw.toLowerCase()];\r\n  if (preset) {\r\n    return preset;\r\n  }\r\n\r\n  return raw.includes('gradient(')\r\n    ? raw\r\n    : `linear-gradient(180deg, ${raw} 0%, ${raw} 100%)`;\r\n}\r\n\r\n/** Create the frontend tool that applies a requested CSS gradient. */\r\nexport function createBackgroundTool(\r\n  background: WritableSignal<string>,\r\n): FrontendToolConfig<BackgroundToolArgs> {\r\n  return {\r\n    name: 'change_background',\r\n    description: 'Change the application background to a CSS gradient.',\r\n    parameters: z.object({\r\n      background: z.string().optional(),\r\n      color: z.string().optional(),\r\n    }),\r\n    handler: async (args) => {\r\n      const next = resolveGradient(args.background ?? args.color);\r\n      background.set(next);\r\n      return { background: next };\r\n    },\r\n  };\r\n}\r\n",
  "src/app/features/tools/tools-chat.component.ts": "/**\r\n * Mounts all three of the guide's frontend-tool paths against one chat.\r\n *\r\n * `registerRenderToolCall` — the tool runs on the server (the LlamaIndex\r\n * agent's weather tool) and the browser only renders its call, through\r\n * WeatherCardComponent.\r\n *\r\n * `registerComponent` — display only. `show_incident` has neither a handler\r\n * nor a tool on the agent: the frontend declares it, CopilotKit forwards it\r\n * over AG-UI, and the agent calls it purely to put IncidentCardComponent on\r\n * screen. Core inserts an empty tool result, so the turn completes without an\r\n * invented result being written into the thread.\r\n *\r\n * `registerFrontendTool` — the tool runs in the browser. `change_background`\r\n * has a handler and no component, so it renders nothing in chat; its result is\r\n * the page itself changing. The registration is removed when this injector is\r\n * destroyed.\r\n *\r\n * The guide's other `registerFrontendTool` sample is a second `getWeather`\r\n * that runs in the browser. It is not mounted: it would collide with the\r\n * server-side tool of the same name, and it calls an `/api/weather` endpoint\r\n * this repo does not serve.\r\n *\r\n * https://docs.copilotkit.ai/angular/llamaindex/guides/frontend-tools-generative-ui\r\n */\r\nimport { Component, signal } from '@angular/core';\r\nimport {\r\n  CopilotSidebar,\r\n  registerComponent,\r\n  registerFrontendTool,\r\n  registerRenderToolCall,\r\n} from '@copilotkit/angular';\r\nimport { z } from 'zod';\r\n\r\nimport {\r\n  DEFAULT_BACKGROUND,\r\n  createBackgroundTool,\r\n} from './tool-feature-model';\r\nimport { IncidentCardComponent } from './incident-card.component';\r\nimport { WeatherCardComponent } from './weather-card.component';\r\n\r\n@Component({\r\n  selector: 'app-tools-chat',\r\n  imports: [CopilotSidebar],\r\n  template: `\r\n    <div\r\n      style=\"height: 100%; display: flex; flex-direction: column; gap: 0.75rem; padding: 0.75rem; transition: background 400ms ease\"\r\n      [style.background]=\"background()\"\r\n    >\r\n        <copilot-sidebar />\r\n\r\n    </div>\r\n  `,\r\n})\r\nexport class ToolsChatComponent {\r\n  /** Written by the agent through the change_background handler. */\r\n  protected readonly background = signal(DEFAULT_BACKGROUND);\r\n\r\n  constructor() {\r\n    registerRenderToolCall({\r\n      name: 'getWeather',\r\n      args: z.object({ city: z.string() }),\r\n      component: WeatherCardComponent,\r\n    });\r\n\r\n    registerComponent({\r\n      name: 'show_incident',\r\n      description: 'Show one incident from the incident table.',\r\n      parameters: z.object({\r\n        id: z.string().describe('The incident id, such as INC-4711'),\r\n        severity: z.string().describe('One of sev1, sev2, sev3'),\r\n      }),\r\n      component: IncidentCardComponent,\r\n    });\r\n\r\n    registerFrontendTool(createBackgroundTool(this.background));\r\n  }\r\n}\r\n",
  "src/app/features/tools/weather-card.component.ts": "/**\r\n * \"Render a tool result\", verbatim.\r\n * https://docs.copilotkit.ai/angular/llamaindex/guides/frontend-tools-generative-ui\r\n */\r\nimport { Component, input } from '@angular/core';\r\nimport { type AngularToolCall, type ToolRenderer } from '@copilotkit/angular';\r\n\r\ntype WeatherArgs = { city: string };\r\n\r\n@Component({\r\n  selector: 'app-weather-card',\r\n  template: `\r\n    @let call = toolCall();\r\n    @if (call.status === \"complete\") {\r\n      <article>\r\n        <strong>{{ call.args.city }}</strong>\r\n        <p>{{ call.result }}</p>\r\n      </article>\r\n    } @else {\r\n      <p>Loading weather for {{ call.args.city ?? \"…\" }}</p>\r\n    }\r\n    <p>Tool Call done </p>\r\n  `,\r\n})\r\nexport class WeatherCardComponent implements ToolRenderer<WeatherArgs> {\r\n  readonly toolCall = input.required<AngularToolCall<WeatherArgs>>();\r\n}\r\n",
};

export function readSource(path: string): string {
  return SOURCES[path] ?? `// Source not generated for ${path}. Run: npm run gen:sources`;
}
